/// Everyone walking with the player, by their own identity.
///
/// It is the identity that matters: the same `id` on both sides of a
/// journey, or of a spell in a camp, is what says the character was moved
/// rather than replaced.
fn print_party(party: &burngfx::game::Party) {
    for who in &party.companions {
        let mut line = String::from("   with you: id ");
        push_num(&mut line, who.id as u32);
        line.push_str(", ");
        push_num(&mut line, who.pack.len() as u32);
        line.push_str(" item(s), food ");
        push_num(&mut line, who.needs.food.max(0) as u32);
        line.push_str(", water ");
        push_num(&mut line, who.needs.water.max(0) as u32);
        line.push_str(", health ");
        push_num(&mut line, who.needs.health.max(0) as u32);
        println_(&line);
    }
}

/// Every camp in the world, once a day: who holds it, what it is making and
/// how far along, and what each of its people has left.
///
/// **This is a regression instrument, not part of the game.** It reports an
/// opponent's people, which the original never tells a player — its
/// statistics screen counts the active player and its info mode refuses to
/// open anybody else's place. `watch` on the command line is the whole of
/// the difference.
fn print_camps_watch(camps: &burngfx::game::Camps, pack: &Pack, gam: Option<&Gamdat>,
                     types: &ItemTypes, productions: &burngfx::production::Productions, me: usize) {
    for (location, camp) in camps.iter() {
        let Some(owner) = camp.owner else { continue };
        let mut line = String::from("   watch ");
        line.push_str(&location_name(pack, gam, location));
        line.push_str(": ");
        line.push_str(&whose(Some(owner), me));
        line.push_str(", making ");
        line.push_str(
            &camp
                .production
                .and_then(|p| productions.get(p))
                .and_then(|p| types.index_of(&p.produce))
                .map(|kind| item_name(pack, types, kind))
                .unwrap_or_else(|| String::from("nothing")),
        );
        line.push_str(" (");
        push_num(&mut line, camp.progress.max(0.0) as u32);
        line.push(')');
        for who in &camp.residents {
            line.push_str(", id ");
            push_num(&mut line, who.id as u32);
            if let Some(record) = who.origin {
                line.push_str(" record ");
                push_num(&mut line, record as u32);
            }
            line.push_str(" food ");
            push_num(&mut line, who.needs.food.max(0) as u32);
            line.push_str(" water ");
            push_num(&mut line, who.needs.water.max(0) as u32);
            line.push_str(" health ");
            push_num(&mut line, who.needs.health.max(0) as u32);
            line.push_str(" carrying ");
            push_num(&mut line, who.pack.len() as u32);
        }
        println_(&line);
    }
}

/// **Which renderer this run is drawing with, as SDL reports it.** Asked for
/// explicitly by `sdlmini` and read back here, so that a run on the wrong path
/// says so on its first line instead of looking like any other hang.
fn print_renderer(screen: &Screen) {
    let mut line = String::from("renderer: ");
    line.push_str(screen.renderer_name());
    println_(&line);
}

fn print_day(day: u16, needs: &burngfx::game::CharacterNeeds, lost: i32) {
    let mut line = String::from("day ");
    push_num(&mut line, day as u32);
    line.push_str(": food ");
    push_num(&mut line, needs.food.max(0) as u32);
    line.push_str(", water ");
    push_num(&mut line, needs.water.max(0) as u32);
    line.push_str(", health ");
    push_num(&mut line, needs.health.max(0) as u32);
    if lost > 0 {
        line.push_str(" (went without, -");
        push_num(&mut line, lost as u32);
        line.push(')');
    }
    println_(&line);
}

fn print_drank(name: &str, before: i32, after: i32, max: i32) {
    let mut line = String::from("   drank ");
    line.push_str(name);
    line.push_str(", water ");
    push_num(&mut line, before as u32);
    line.push_str(" -> ");
    push_num(&mut line, after as u32);
    line.push('/');
    push_num(&mut line, max as u32);
    println_(&line);
}

/// The save's own fingerprint goes in the line, so two runs can be compared
/// without reading the files — which on a guest means without a share.
/// A save naming traders this world has none of. Not fatal — everything
/// else loaded — but it means the save and the world disagree about who
/// exists, and that is worth saying rather than swallowing.
/// What the world's shops opened with, said once so a run can be compared.
fn print_traders(
    traders: &burngfx::trader::Traders,
    lists: &burngfx::trader::StockLists,
    prices: &burngfx::trade::Prices,
) {
    let stocked = traders.iter().filter(|t| !t.stock.is_empty()).count();
    let mut line = String::from("traders: ");
    push_num(&mut line, traders.len() as u32);
    line.push_str(" placed, ");
    push_num(&mut line, stocked as u32);
    line.push_str(" with stock, ");
    push_num(&mut line, lists.len() as u32);
    line.push_str(" list(s)");
    if prices.is_empty() {
        line.push_str(", no prices in the pack");
    }
    println_(&line);
}

/// Everything lying on the ground here, where it is and what it is.
///
/// **A reading of the world, not a change to it.** Piles are drawn as marks
/// a few pixels across and a script has to name one by position; hunting for
/// them by trying coordinates is guesswork that reports nothing when it
/// fails. This lists what the world actually holds, so a `mapclick` can name
/// a real one.
fn print_piles(ground: &[burngfx::spawn::Dropped], location: usize, types: &ItemTypes) {
    let mut seen: Vec<Point> = Vec::new();
    for item in ground.iter().filter(|d| d.location == location) {
        // Things within a stride of each other open as one pile, so list
        // them the way a click would find them.
        if seen.iter().any(|p| within(*p, item.at, PICK_REACH)) {
            continue;
        }
        seen.push(item.at);
        let together = pile_at(ground, location, item.at);
        let mut line = String::from("   pile at ");
        push_num(&mut line, item.at.x.max(0) as u32);
        line.push(',');
        push_num(&mut line, item.at.y.max(0) as u32);
        line.push_str(": ");
        for (n, &i) in together.iter().enumerate() {
            if n > 0 {
                line.push_str(", ");
            }
            line.push_str(ground.get(i).and_then(|d| types.name_of(d.kind)).unwrap_or("?"));
        }
        println_(&line);
    }
    if seen.is_empty() {
        println_("   nothing on the ground here");
    }
}

/// Where the doors are, in map coordinates a `mapclick` can use.
///
/// The same reason as [`print_piles`]: the game outlines them on screen,
/// but a script has to name one by position, and looking for a doorway a
/// dozen pixels wide by trying coordinates reports nothing when it misses.
/// `Player.MarkVisited`, for `seat` standing at `at`. A seat with no history
/// yet — a new game, or a v1.2 save from before it was kept — starts as
/// `EnsureVisitedLocations` migrates one: its camps and their neighbours.
fn mark_visited(visited: &mut Vec<(usize, Vec<usize>)>, seat: usize, at: usize, camps: &burngfx::game::Camps,
                gam: Option<&Gamdat>) {
    let entry = match visited.iter().position(|(s, _)| *s == seat) {
        Some(i) => i,
        None => {
            let mut places: Vec<usize> = Vec::new();
            for (i, l) in gam.map_or(&[][..], |g| &g.locations[..]).iter().enumerate() {
                if camps.get(i).and_then(|c| c.owner) == Some(seat) {
                    places.push(i);
                    places.extend(l.roads.iter().map(|r| r.neighbour));
                }
            }
            places.sort_unstable();
            places.dedup();
            visited.push((seat, places));
            visited.len() - 1
        }
    };
    let places = &mut visited[entry].1;
    if let Err(i) = places.binary_search(&at) {
        places.insert(i, at);
    }
}

fn has_visited(visited: &[(usize, Vec<usize>)], seat: usize, place: usize) -> bool {
    visited.iter().any(|(s, p)| *s == seat && p.binary_search(&place).is_ok())
}

/// The film a door shows before what it opens, or instead of it
/// (`LocationScene`'s entrance switch): said in the log, and what the pack
/// lacks for it said once.
fn door_film<'a>(pack: &Pack<'a>, room_id: Option<u8>, v12: bool) -> Option<films::Film<'a>> {
    let kind = room_id.and_then(films::Kind::of_door)?;
    let f = films::Film::open(pack, kind, String::new(), sdlmini::ticks(), v12);
    if let Some(gap) = f.missing() {
        let mut line = String::from("film: the pack has no ");
        line.push_str(gap);
        println_(&line);
    }
    let mut line = String::from("film: ");
    line.push_str(kind.label());
    println_(&line);
    Some(f)
}

fn print_doors(map: &Map, scene: &Scene) {
    let mut line = String::from("   doors: ");
    let mut n = 0;
    for (i, e) in map.entrances.iter().enumerate() {
        if n > 0 {
            line.push_str("  ");
        }
        push_num(&mut line, (e.left + e.width / 2).max(0) as u32);
        line.push(',');
        push_num(&mut line, (e.top + e.height / 2).max(0) as u32);
        // What kind of room it is, because a surgery and a storeroom look
        // the same from outside and only one of them can treat anybody.
        line.push('(');
        line.push_str(match scene.room_ids.get(i).copied().map(matmap::RoomType::from_room_id) {
            Some(matmap::RoomType::Doctor) => "doctor",
            Some(matmap::RoomType::Trader) => "trader",
            Some(matmap::RoomType::WaterSource) => "water",
            Some(matmap::RoomType::Rope) => "rope",
            Some(matmap::RoomType::Pub) => "pub",
            Some(matmap::RoomType::Church) => "church",
            Some(matmap::RoomType::Restaurant) => "restaurant",
            Some(matmap::RoomType::Scene) => "scene",
            _ => "room",
        });
        line.push(')');
        n += 1;
    }
    if n == 0 {
        line.push_str("(none)");
    }
    println_(&line);
}

/// Every location that holds anything, in one listing.
///
/// **Read from the world that was generated**, not from the rules that
/// generated it: what a place actually ended up with is the only thing a
/// test can aim at.
#[allow(clippy::too_many_arguments)]
fn print_world_contents(
    rooms: &RoomItems,
    ground: &[burngfx::spawn::Dropped],
    types: &ItemTypes,
    gam: Option<&Gamdat>,
    pack: &Pack,
    world: &Map,
) {
    println_("world contents:");
    for location in 0..burngfx::gamdat::LOCATION_COUNT {
        let in_rooms: usize =
            rooms.iter().filter(|(l, _, b)| *l == location && !b.is_empty()).count();
        let outside = ground.iter().filter(|d| d.location == location).count();
        if in_rooms == 0 && outside == 0 {
            continue;
        }
        let mut line = String::from("   ");
        push_num(&mut line, location as u32);
        line.push_str(" @");
        // Where to click on the world map to choose it. Same reason as the
        // doors: the marker is small and guessing at it reports nothing.
        match world.entrances.get(location) {
            Some(e) => {
                push_num(&mut line, (e.left + e.width / 2).max(0) as u32);
                line.push(',');
                push_num(&mut line, (e.top + e.height / 2).max(0) as u32);
            }
            None => line.push('?'),
        }
        line.push(' ');
        line.push_str(&location_name(pack, gam, location));
        if gam.and_then(|g| g.locations.get(location)).is_some_and(|l| l.is_city) {
            line.push_str(" (city)");
        }
        // The danger too, because a script that wants to stand in gas has to
        // know where there is some.
        match gam.and_then(|g| g.locations.get(location)).map(|l| (l.danger, l.danger_amount)) {
            Some((burngfx::gamdat::Danger::Gas, n)) => {
                line.push_str(" gas ");
                push_num(&mut line, n as u32);
            }
            Some((burngfx::gamdat::Danger::Radiation, n)) => {
                line.push_str(" radiation ");
                push_num(&mut line, n as u32);
            }
            _ => {}
        }
        line.push_str(": ");
        push_num(&mut line, outside as u32);
        line.push_str(" on the ground, rooms hold");
        for (l, room, bag) in rooms.iter() {
            if l != location || bag.is_empty() {
                continue;
            }
            line.push_str(" [");
            push_num(&mut line, room as u32);
            line.push(':');
            for (n, kind) in bag.iter().enumerate() {
                if n > 0 {
                    line.push(',');
                }
                line.push(' ');
                line.push_str(types.name_of(kind).unwrap_or("?"));
            }
            line.push(']');
        }
        println_(&line);
    }
}

/// What the rooms of this location hold.
///
/// **`LoadItems` skips a city when it stocks rooms — which is not the same
/// as a city's rooms being empty.** Other paths reach them: New Sandez has
/// ammunition in room 0 from the danger spoils, which are tested per block
/// rather than per location. So the ordinary stock is elsewhere, but "a
/// city holds nothing" is a claim the world itself disproves, and reading
/// the world is why this exists.
/// What the leader is carrying, slot by slot, **with the empty slots shown**.
///
/// A pack keeps its holes: spending the meat out of slot 0 does not shift the
/// bottle down into it. That matters to anybody writing a script against the
/// panel, and not knowing it cost an afternoon of clicking at the wrong
/// squares.
fn print_carrying(carried: &ItemBag, pack: &Pack, types: &ItemTypes) {
    let mut line = String::from("   carrying:");
    for slot in 0..carried.capacity() {
        line.push(' ');
        push_num(&mut line, slot as u32);
        line.push('=');
        match carried.get(slot) {
            Some(kind) => line.push_str(&item_name(pack, types, kind)),
            None => line.push('-'),
        }
    }
    println_(&line);
}

fn print_rooms(rooms: &RoomItems, location: usize, types: &ItemTypes) {
    let mut any = false;
    for (l, room, bag) in rooms.iter() {
        if l != location || bag.is_empty() {
            continue;
        }
        any = true;
        let mut line = String::from("   room ");
        push_num(&mut line, room as u32);
        line.push_str(": ");
        for (n, kind) in bag.iter().enumerate() {
            if n > 0 {
                line.push_str(", ");
            }
            line.push_str(types.name_of(kind).unwrap_or("?"));
        }
        println_(&line);
    }
    if !any {
        println_("   nothing in the rooms here");
    }
}

/// Whose table the player is at.
/// Somebody is gone. Said plainly, with what it cost: a name, a place, and
/// whether the camp went with them.
/// Somebody came back. Said, because a player who lost a man and can hire
/// him again a week later should be told rather than left to notice.
fn print_returned(
    back: &burngfx::game::Returned,
    class: burngfx::gamdat::CharClass,
    pack: &Pack,
    gam: Option<&Gamdat>,
) {
    let mut line = String::from("a ");
    line.push_str(class_name(class));
    line.push_str(" is back at ");
    line.push_str(&location_name(pack, gam, back.location));
    line.push_str(": health ");
    push_num(&mut line, back.needs.health.max(0) as u32);
    line.push_str(", food ");
    push_num(&mut line, back.needs.food.max(0) as u32);
    line.push_str(", water ");
    push_num(&mut line, back.needs.water.max(0) as u32);
    // A dog is not somebody to offer work to; `can_be_hired` is the same
    // test the greeting makes.
    line.push_str(if class.can_be_hired() {
        " - and open to work again"
    } else {
        " - and on its feet again"
    });
    println_(&line);
}

fn print_death(
    death: &burngfx::game::Death,
    pack: &Pack,
    gam: Option<&Gamdat>,
    location: usize,
) {
    let mut line = String::from("companion ");
    push_num(&mut line, death.id as u32);
    line.push_str(" died");
    match death.at {
        Some(_) => {
            line.push_str(" camped at ");
            line.push_str(&location_name(pack, gam, location));
        }
        None => line.push_str(" on the road with you"),
    }
    if !death.dropped.is_empty() {
        line.push_str(", dropping ");
        push_num(&mut line, death.dropped.len() as u32);
        line.push_str(" thing(s)");
    }
    println_(&line);
    if death.camp_lost {
        let mut said = String::from("   the last one there: ");
        said.push_str(&location_name(pack, gam, location));
        said.push_str(" is nobody's again, and makes nothing");
        println_(&said);
    }
}

fn print_diner(service: burngfx::diner::Service) {
    println_(match service {
        burngfx::diner::Service::Pub =>
            "the pub: put things on the table, c for a companion's pack, enter to drink",
        burngfx::diner::Service::Restaurant =>
            "the restaurant: put things on the table, c for a companion's pack, enter to eat",
    });
}

/// Who took what, who was too far off, and what nobody had room for.
fn print_served(service: burngfx::diner::Service, s: &burngfx::diner::Standing) {
    let mut line = String::from(match service {
        burngfx::diner::Service::Pub => "drank ",
        burngfx::diner::Service::Restaurant => "ate ",
    });
    push_num(&mut line, s.worth.max(0) as u32);
    line.push(':');
    push_shares(&mut line, s);
    println_(&line);
}

/// `you 3->5, companion 1 4->5, companion 2 out of reach (80), 2 wasted`.
fn push_shares(line: &mut String, s: &burngfx::diner::Standing) {
    for (n, share) in s.shares.iter().enumerate() {
        line.push_str(if n == 0 { " " } else { ", " });
        if share.who == 0 {
            line.push_str("you");
        } else {
            line.push_str("companion ");
            push_num(line, share.who as u32);
        }
        match share.out_of_reach {
            Some(d) => {
                line.push_str(" out of reach (");
                push_num(line, d.max(0) as u32);
                line.push(')');
            }
            None => {
                line.push(' ');
                push_num(line, share.from.max(0) as u32);
                line.push_str("->");
                push_num(line, share.to.max(0) as u32);
            }
        }
    }
    if s.wasted > 0 {
        line.push_str(", ");
        push_num(line, s.wasted as u32);
        line.push_str(" wasted");
    }
}

fn diner_refusal(why: burngfx::diner::Refusal) -> String {
    use burngfx::diner::Refusal::*;
    match why {
        NothingOnTheTable => String::from("put something on the table"),
        TooMuchOnTheTable => String::from("the table holds four"),
        NoSuchSlot | SlotNamedTwice => String::from("that pick no longer means anything"),
        WorthNothing => String::from("that is worth nothing here: nothing taken"),
        OutOfReach { companion, distance } => {
            let mut s = String::from("companion ");
            push_num(&mut s, companion as u32);
            s.push_str(" is ");
            push_num(&mut s, distance.max(0) as u32);
            s.push_str(" away: out of reach, cannot pay");
            s
        }
    }
}

/// A `burn?N` line with its count filled in. `|E` is the number, and
/// `plural|#singular` chooses by it — `for |E days.|#for 1 day.`.
fn counted(pack: &Pack, index: u32, n: i32) -> String {
    let raw = resolve(pack, &burn_ref(index)).unwrap_or_default();
    let chosen = match raw.split_once("|#") {
        Some((_, one)) if n == 1 => String::from(one),
        Some((many, _)) => String::from(many),
        None => raw,
    };
    let mut number = String::new();
    push_num(&mut number, n.max(0) as u32);
    chosen.replace("|E", &number)
}

/// The pub or the restaurant: its picture, the table, the pack showing, the
/// scene's own three lines, and what the model says would happen.
#[allow(clippy::too_many_arguments)]
fn draw_diner_panel(canvas: &mut Canvas, text: &Text, pack: &Pack, types: &ItemTypes,
                    table: &Dining, showing: &ItemBag, on_table: &[usize], viewing: usize,
                    reach: Option<i32>,
                    standing: Result<burngfx::diner::Standing, burngfx::diner::Refusal>) {
    use burngfx::diner::{Refusal, Service};
    const INK: u32 = 0xFFF0_F0F0;
    const DIM: u32 = 0xFFB0_B0C8;
    const PICKED: u32 = 0xFF70_D0F0;
    const SHADE: u32 = 0xC000_0000;

    let mut key = [0u8; NAME_LEN];
    let picture = names::scene_image(&mut key, table.service.background(table.room_id))
        .and_then(|n| start_view::image(pack, key_str(&key[..n])));
    match &picture {
        Some(img) => draw_interior(canvas, img),
        None => {
            for px in canvas.px.iter_mut() {
                let (r, g, b) = ((*px >> 16) & 0xFF, (*px >> 8) & 0xFF, *px & 0xFF);
                *px = 0xFF00_0000 | (r / 3) << 16 | (g / 3) << 8 | (b / 3);
            }
        }
    }

    let origin = room_origin(canvas);
    draw_item_grid(canvas, pack, origin, &diner_grid(),
                   &ItemBag::with(burngfx::diner::TABLE, on_table), types);
    draw_item_grid(canvas, pack, origin, &pack_grid(), showing, types);
    for &(bag, slot) in &table.picks {
        if bag == viewing {
            if let Some(at) = pack_grid().slot_at(slot) {
                canvas.outline(origin.x + at.x - 1, origin.y + at.y - 1, 34, 34, PICKED);
            }
        }
    }

    // The scene's words: `+9` for an empty table, `+6` for one worth
    // nothing, `+3` once served, and the offer itself otherwise.
    let base = table.service.text_base() as u32;
    let (offset, count) = match (&standing, table.served) {
        (_, Some(worth)) => (3, worth),
        (Err(Refusal::NothingOnTheTable), None) => (9, 0),
        (Err(Refusal::WorthNothing), None) => (6, 0),
        // A v1.2 table worth nothing, not yet served (`value == 0`).
        (Ok(s), None) if s.worth == 0 => (9, 0),
        (Ok(s), None) => (0, s.worth),
        (Err(_), None) => (9, 0),
    };
    // Where the scene puts them: centred on x 237, from y 4, nine apart.
    let mut y = origin.y + 4;
    for k in 0..3 {
        let said = counted(pack, base + offset + k, count);
        if !said.is_empty() {
            let w = text.width(&said);
            canvas.fill(origin.x + 237 - w / 2 - 2, y - 1, w + 4, 11, SHADE);
            text.draw(canvas, &said, origin.x + 237 - w / 2, y, INK);
        }
        y += 11;
    }
    canvas.fill(0, canvas.h as i32 - 27, canvas.w as i32, 27, SHADE);

    let mut model = String::new();
    match (&standing, reach) {
        (_, Some(d)) => {
            model.push_str("this companion is ");
            push_num(&mut model, d.max(0) as u32);
            model.push_str(" away: out of reach, cannot pay");
        }
        (Ok(s), None) => {
            push_shares(&mut model, s);
            model.push_str(match table.service {
                Service::Pub => " - enter to drink",
                Service::Restaurant => " - enter to eat",
            });
        }
        (Err(why), None) => model = diner_refusal(*why),
    }
    let y = canvas.h as i32 - 24;
    text.draw(canvas, model.trim_start(), (canvas.w as i32 - text.width(model.trim_start())) / 2, y, PICKED);
    let hint = "click to put on the table, c for a companion, esc to leave";
    text.draw(canvas, hint, (canvas.w as i32 - text.width(hint)) / 2, y + 11, DIM);
}

/// Said once, at the start: this game has somebody on the other side, and it
/// was asked for rather than assumed.
fn print_rival_started(location: usize, pack: &Pack, gam: Option<&Gamdat>, experience: i32,
                       items: usize) {
    let mut line = String::from("a machine player starts at ");
    line.push_str(&location_name(pack, gam, location));
    line.push_str(": experience ");
    push_num(&mut line, experience.max(0) as u32);
    line.push_str(", ");
    push_num(&mut line, items as u32);
    line.push_str(" item(s), the same start the player is given");
    println_(&line);
}

fn print_amiga_turn(player: usize, log: &[String], rival: &burngfx::rival::Rival,
                    fallen: &amiga_seat::Fallen, pack: &Pack, gam: Option<&Gamdat>) {
    let Some(ai) = rival.amiga.as_ref() else { return };
    let mut line = String::from("player ");
    push_num(&mut line, player as u32);
    line.push_str(" (amiga) at ");
    line.push_str(&location_name(pack, gam, rival.at));
    line.push_str(if rival.journey.is_some() { ", leaving" } else { ", staying" });
    line.push_str(", group ");
    push_num(&mut line, 1 + rival.party.len() as u32);
    line.push_str(", pending ");
    line.push_str(if ai.maintenance_pending { "yes" } else { "no" });
    println_(&line);
    for l in log {
        let mut line = String::from("   ");
        line.push_str(l);
        println_(&line);
    }
    if fallen.people > 0 || !fallen.human_leaders.is_empty() || !fallen.leaders.is_empty() {
        let mut line = String::from("   the duel killed ");
        push_num(&mut line, (fallen.people + fallen.leaders.len() + fallen.human_leaders.len()) as u32);
        line.push(':');
        for w in &fallen.who {
            line.push(' ');
            line.push_str(w);
            line.push(';');
        }
        for p in &fallen.leaders {
            line.push_str(" the leader of player ");
            push_num(&mut line, *p as u32);
            line.push(';');
        }
        for _ in &fallen.human_leaders {
            line.push_str(" the human leader;");
        }
        line.pop();
        println_(&line);
    }
}

/// The rules of a v1.2 game's day, as `World.Turn` needs them: the preset's
/// survival, stabilization, water and production rules, the Amiga
/// opponent's healing threshold of 50 for its seats, and who is a doctor.
fn v12_world(book: &burngfx::rules::RuleBook, rivals: &[burngfx::rival::Rival], people: &People, gam: Option<&Gamdat>)
             -> burngfx::v12_day::V12World {
    let mut thresholds = [None; 4];
    for r in rivals.iter().filter(|r| r.amiga.is_some()) {
        if let Some(t) = thresholds.get_mut(r.player) {
            *t = Some(burngfx::amiga_ai::HEALING_THRESHOLD);
        }
    }
    burngfx::v12_day::V12World {
        survival: book.rules.survival,
        stabilization: book.rules.doctor_stabilization,
        water_output: book.rules.water_output,
        food_production: book.rules.food_production,
        thresholds,
        doctors: (0..people.len())
            .filter_map(|i| people.get(i))
            .filter(|p| p.class == burngfx::gamdat::CharClass::Doctor)
            .map(|p| p.record)
            .collect(),
        dangers: gam.map_or(Vec::new(), |g| g.locations.iter().map(|l| l.danger).collect()),
        gas_immune: book.rules.gas_immune_faces.clone(),
        radiation_immune: book.rules.radiation_immune_faces.clone(),
        faces: (0..people.len()).filter_map(|i| people.get(i)).map(|p| (p.record, p.face_id)).collect(),
        technicians: (0..people.len())
            .filter_map(|i| people.get(i))
            .filter(|p| p.class == burngfx::gamdat::CharClass::Technician)
            .map(|p| p.record)
            .collect(),
        technician_bonus: book.rules.technician_food_bonus,
        cities: gam.map_or(Vec::new(), |g| g.locations.iter().map(|l| l.is_city).collect()),
    }
}

/// A travelling group's day: v1.2's upkeep for a v1.2 game, the legacy
/// `party_day` otherwise.
fn group_day(v12: Option<&burngfx::v12_day::V12World>, seat: usize, travelling: bool,
             human_at: Option<(usize, u8)>, needs: &mut burngfx::game::CharacterNeeds,
             leader_e: &mut burngfx::danger::Exposure,
             pack: &mut ItemBag, party: &mut burngfx::game::Party, types: &ItemTypes) -> game::DayOutcome {
    let Some(v) = v12 else { return game::party_day(needs, pack, party, types) };
    let upkeep = burngfx::v12_day::Upkeep {
        survival: v.survival,
        stabilization: v.stabilization,
        doctor: party.companions.iter().any(|c| c.origin.is_some_and(|o| v.doctors.contains(&o))),
        threshold: v.thresholds.get(seat).copied().flatten(),
        travelling,
    };
    let health_before = needs.health;
    // `ApplyDaily` for a human's group where it stands; an AI player's own
    // group is spared.
    let hazard = human_at.map(|(location, face)| {
        let danger = v.dangers.get(location).copied().unwrap_or(burngfx::gamdat::Danger::None);
        burngfx::v12_day::Hazard {
            danger,
            immune: match danger {
                burngfx::gamdat::Danger::Gas => &v.gas_immune,
                burngfx::gamdat::Danger::Radiation => &v.radiation_immune,
                burngfx::gamdat::Danger::None => &[],
            },
            leader_face: face,
            faces: &v.faces,
            exempt: false,
        }
    });
    // `World.Turn`'s own loop over the group, the doctor asked for each.
    let out = burngfx::v12_day::party_day_exposed(needs, leader_e, pack, party, types, upkeep, hazard.as_ref(), Some(&v.doctors));
    game::DayOutcome { health_before, died: out.leader_died, deaths: out.deaths, killed_by_danger: out.leader_hazard,
                       dropped: out.leader_dropped, ..game::DayOutcome::default() }
}

/// A difficulty's settings. v1.2's `game.txt` keeps `start_experience`
/// among its `[rules]`, for every difficulty (`RuleBook.Settings`), where
/// the legacy files have it per difficulty.
fn settings_of(text: Option<&str>, difficulty: u16, book: Option<&burngfx::rules::RuleBook>) -> GameSettings {
    let mut settings = text.map(|t| GameSettings::parse(t, difficulty)).unwrap_or_default();
    if let Some(b) = book {
        settings.start_experience = b.rules.start_experience;
        // v1.2 names the people's interval `npc_spawn` (`npc_respawn` is
        // only its fallback).
        settings.npc_respawn = b.difficulty[(difficulty as usize).min(2)].npc_spawn;
    }
    settings
}

fn print_v12_start(seat: usize, start: &burngfx::v12_economy::Start, types: &ItemTypes) {
    let mut line = String::from("v1.2 start: player ");
    push_num(&mut line, seat as u32);
    line.push_str(" health ");
    push_num(&mut line, start.health.max(0) as u32);
    line.push_str(", food ");
    push_num(&mut line, start.food.max(0) as u32);
    line.push_str(", water ");
    push_num(&mut line, start.water.max(0) as u32);
    line.push_str(", experience ");
    push_num(&mut line, start.experience.max(0) as u32);
    line.push_str(", carrying");
    for &kind in &start.items {
        line.push(' ');
        line.push_str(types.name_of(kind).unwrap_or("?"));
    }
    println_(&line);
}

/// `Player.BaseExperience` of a v1.2 human: what he started with.
fn v12_base_experience(book: &burngfx::rules::RuleBook, gam: Option<&Gamdat>, seat: usize) -> i32 {
    match book.rules.player_setup {
        burngfx::rules::PlayerSetup::RemasterSettings => book.rules.start_experience,
        burngfx::rules::PlayerSetup::DosGamdat => {
            gam.and_then(|g| g.characters.get(seat)).map_or(0, |c| c.experience as i32)
        }
    }
}

/// A v1.2 preset's `[region_item_N]` sections, in order, as long as they
/// run on: the items, their rate and their locations (counted from nought).
fn region_items(book: &burngfx::rules::RuleBook) -> Vec<(burngfx::settings::Spawn, Vec<usize>)> {
    let mut out = Vec::new();
    for n in 0.. {
        let mut name = String::from("region_item_");
        push_num(&mut name, n as u32);
        let Some(section) = book.section(&name) else { break };
        let locations: Vec<usize> = section.ints("locations").into_iter().filter(|&l| l > 0).map(|l| (l - 1) as usize).collect();
        let spawn = burngfx::settings::Spawn {
            filter: burngfx::settings::Filter::parse(section.string("items")),
            // `FromStrings`: no rate is one.
            rate: match section.string("rate").trim() {
                "" => burngfx::settings::Rate { min: 1, max: 1 },
                r => burngfx::settings::Rate::parse(r),
            },
        };
        out.push((spawn, locations));
    }
    out
}

/// `PopulateInitialItems` for the characters: each item `gam.dat` gives a
/// record, to that trader's stock or that person's pack.
fn give_gamdat_held(held: &[(usize, usize)], traders: &mut burngfx::trader::Traders, people: &mut People) {
    for &(record, kind) in held {
        if let Some(i) = (0..traders.len()).find(|&i| traders.get(i).is_some_and(|t| t.record == record)) {
            if let Some(t) = traders.get_mut(i) {
                t.stock.push(kind);
            }
            continue;
        }
        people.hand_out(record, kind);
    }
}

/// Extended's rule that a trader holding a firearm is offered no other
/// (`Root.Rules == RuleSet.Extended`).
fn one_firearm(identity: burngfx::rules::Identity) -> bool {
    matches!(identity, burngfx::rules::Identity::V12 { preset: burngfx::rules::RuleSet::Extended, .. })
}

/// How many items of each world-limited group (`trader_world_limit`) lie
/// anywhere but in a trader's stock: rooms, ground, everybody's packs.
fn limited_groups(types: &ItemTypes, rooms: &RoomItems, ground: &[burngfx::spawn::Dropped], people: &People,
                  packs: &[&ItemBag], parties: &[&burngfx::game::Party], camps: &burngfx::game::Camps)
                  -> Vec<(String, usize)> {
    let mut out: Vec<(String, usize)> = Vec::new();
    let mut count = |kind: usize| {
        if types.get(kind).is_none_or(|t| t.trader_world_limit <= 0 && t.trader_world_group.is_none()) {
            return;
        }
        let g = burngfx::trader::world_group(types, kind);
        match out.iter_mut().find(|(n, _)| *n == g) {
            Some(e) => e.1 += 1,
            None => out.push((g, 1)),
        }
    };
    for (_, _, bag) in rooms.iter() {
        bag.iter().for_each(&mut count);
    }
    ground.iter().for_each(|d| count(d.kind));
    for i in 0..people.len() {
        if let Some(p) = people.get(i) {
            p.pack.iter().for_each(&mut count);
        }
    }
    for pack in packs {
        pack.iter().for_each(&mut count);
    }
    for party in parties {
        party.companions.iter().flat_map(|c| c.pack.iter()).for_each(&mut count);
    }
    for (_, camp) in camps.iter() {
        camp.residents.iter().flat_map(|r| r.pack.iter()).for_each(&mut count);
    }
    out
}

fn count_of(groups: &[(String, usize)], group: &str) -> usize {
    groups.iter().find(|(n, _)| n == group).map_or(0, |e| e.1)
}

