/// v1.2's `IsAlive` over the seats, in seat order: a human not out whose
/// leader lives, a machine player not dead whose leader lives.
fn alive_players(humans: &[burngfx::save::Human], me: usize, dead: bool, bench: Option<&Benched>,
                 rivals: &[burngfx::rival::Rival]) -> Vec<usize> {
    let mut out: Vec<usize> = humans
        .iter()
        .filter(|h| !h.out)
        .filter(|h| if h.seat == me { !dead } else { bench.is_none_or(|b| b.seat != h.seat || !b.dead) })
        .map(|h| h.seat)
        .collect();
    out.extend(rivals.iter().filter(|r| !r.dead && r.needs.health > 0).map(|r| r.player));
    out.sort_unstable();
    out.dedup();
    out
}

/// `LastRivalDialog.Show`: no face (`SetCharacter(player.Character,
/// conversation, textLinesPerPage: 3)`, `LastRivalDialog.cs:38`), `last_rival.txt`'s three
/// lines with `{total}` the number of cities, and its two answers — "That's
/// enough" the victory, "Finish what I started" play on — all on one page.
fn last_rival_talk(pack: &Pack, face: u8, cities: usize, view: &Viewport) -> talk::Talk {
    let text = localized(pack, "v12/last_rival").and_then(|b| core::str::from_utf8(b).ok()).unwrap_or("");
    let mut total = String::new();
    push_num(&mut total, cities as u32);
    let lines: Vec<String> = text.lines().map(|l| l.trim_end().replace("{total}", &total)).collect();
    let line = |i: usize| lines.get(i).cloned().unwrap_or_default();
    use burngfx::dialog::{Action, Choice};
    let none = Choice { burn: None, action: Action::None };
    talk::Talk {
        who: usize::MAX,
        face,
        conv: burngfx::dialog::Conversation {
            file: 0,
            section: 0,
            choices: [Choice { burn: None, action: Action::Yes }, Choice { burn: None, action: Action::No }, none],
            item: None,
            substitutes: false,
        },
        lines: lines.iter().take(3).cloned().collect(),
        choice_text: [line(3), line(4), String::new()],
        more_text: String::new(),
        pages: burngfx::dialog::Pages { offset: 0, choosing: true },
        hover: None,
        at: talk_at(view),
        per_page: 3,
        show_face: false,
    }
}

fn print_rotted(item: &str, place: &str) {
    let mut line = String::from("rotted away on the ground at ");
    line.push_str(place);
    line.push_str(": ");
    line.push_str(item);
    println_(&line);
}

/// `RadioIntel.IsAvailable` and `Create`, worded as `ShowRadioReport`:
/// the place, its food and water a day, and its defenders — the other
/// players' campers there and the parties of the others standing there —
/// with the threat their strength makes. `None` when the radio has nothing
/// to say about that place: no radio access, a city, where the player
/// stands, his own, or out of reach (v1.3, [`radio_available`]).
#[allow(clippy::too_many_arguments)]
/// A v1.2 game's INFO numbers for `city`: `GetFoodProductionRate`'s food a
/// day and its `MaintenanceBonus` (applied only to a yield), and
/// `Source.Water`.
#[allow(clippy::too_many_arguments)]
fn v12_info_numbers(city: usize, book: &burngfx::rules::RuleBook, g: &Gamdat, camps: &burngfx::game::Camps,
                    rooms: &mut RoomItems, ground: &mut Vec<burngfx::spawn::Dropped>, room_ids: &[Vec<u8>],
                    walk: &[Option<WalkGrid>], types: &ItemTypes, productions: &burngfx::production::Productions,
                    rivals: &[burngfx::rival::Rival], people: &People, springs: &Springs) -> (i32, i32, i32) {
    let water = v12_source_water(city, springs, room_ids, rooms, types, book);
    let v = v12_world(book, rivals, people, Some(g));
    let storage = WorldStorage {
        rooms,
        ground,
        room_ids,
        walk,
        types,
        productions,
        rng: burngfx::spawn::Rng::seeded(0),
        products: Vec::new(),
    };
    let (food, bonus) = camps.get(city).and_then(|c| c.production.map(|p| (c, p))).map_or((0, 0), |(c, p)| {
        let food = burngfx::v12_day::food_rate(city, c, &storage, productions, types, &v, p);
        (food, if food > 0 { burngfx::v12_day::maintenance_bonus(city, c, &v) } else { 0 })
    });
    let mut line = String::from("info (v1.2): food ");
    line.push_str(&panels::num(food - bonus));
    if bonus > 0 {
        line.push('+');
        line.push_str(&panels::num(bonus));
    }
    line.push_str(" a day, water ");
    line.push_str(&panels::num(water));
    println_(&line);
    (food, bonus, water)
}

/// v1.2's `Source.Water`: the spring's day with what is installed in its
/// room (`RuleBook.CalculateWaterOutput`). What INFO and the radio show.
fn v12_source_water(target: usize, springs: &Springs, room_ids: &[Vec<u8>], rooms: &RoomItems, types: &ItemTypes,
                    book: &burngfx::rules::RuleBook) -> i32 {
    springs.get(target).map_or(0, |s| {
        let water_room = room_ids.get(target).and_then(|ids| ids.iter().position(|&id| matmap::RoomType::from_room_id(id) == matmap::RoomType::WaterSource));
        let has = |name: &str| water_room.and_then(|r| rooms.get(target, r)).is_some_and(|b| b.iter().any(|k| types.name_of(k) == Some(name)));
        let industrial = has("item_industrial_pump");
        burngfx::v12_day::water_output(book.rules.water_output, s.refresh, !industrial && has("item_hand_pump"), industrial)
    })
}

/// v1.3's `RadioIntel` (`27b45d3`, "revise radio functionality",
/// `Logic/RadioIntel.cs` at `v1.3`). `HasRadio`: a living member of the
/// group carries an item with `remote_intel` (the leader's pack counts).
fn radio_carried(carried: &ItemBag, party: &burngfx::game::Party, types: &ItemTypes) -> bool {
    burngfx::v12_items::has_function(carried, types, "remote_intel")
        || party.companions.iter().any(|c| c.needs.health > 0 && burngfx::v12_items::has_function(&c.pack, types, "remote_intel"))
}

/// `HasStoredRadio`: one of the place's rooms holds an item with
/// `remote_intel`. Packs of the people camped there do not count.
fn radio_stored(location: usize, rooms: &RoomItems, room_ids: &[Vec<u8>], types: &ItemTypes) -> bool {
    (0..room_ids.get(location).map_or(0, |ids| ids.len()))
        .filter_map(|r| rooms.get(location, r))
        .any(|bag| burngfx::v12_items::has_function(bag, types, "remote_intel"))
}

/// `HasAccess`: a radio carried, or one stored where the player is.
fn radio_access(here: usize, carried: &ItemBag, party: &burngfx::game::Party, rooms: &RoomItems,
                room_ids: &[Vec<u8>], types: &ItemTypes) -> bool {
    radio_carried(carried, party, types) || radio_stored(here, rooms, room_ids, types)
}

/// `IsAvailable`: radio access, and the place is no city, not where the
/// player stands and not his own; and it is a neighbour of where he stands,
/// or of one of his own camps with a radio stored in it (a station).
#[allow(clippy::too_many_arguments)]
fn radio_available(target: usize, me: usize, here: usize, carried: &ItemBag, party: &burngfx::game::Party,
                   camps: &burngfx::game::Camps, rooms: &RoomItems, room_ids: &[Vec<u8>], types: &ItemTypes,
                   gam: &Gamdat) -> bool {
    let Some(place) = gam.locations.get(target) else { return false };
    let mine = |l: usize| camps.get(l).and_then(|c| c.owner) == Some(me);
    if !radio_access(here, carried, party, rooms, room_ids, types) || place.is_city || target == here || mine(target) {
        return false;
    }
    let neighbour_of = |l: usize| gam.locations.get(l).is_some_and(|x| x.roads.iter().any(|r| r.neighbour == target));
    neighbour_of(here)
        || (0..gam.locations.len()).any(|station| mine(station) && radio_stored(station, rooms, room_ids, types) && neighbour_of(station))
}

/// `CanSeeHealth` (INFO's camp people with experience and health): where
/// the player stands, or his own camp with a radio stored in it while he
/// has radio access.
#[allow(clippy::too_many_arguments)]
fn radio_sees_health(location: usize, me: usize, here: usize, carried: &ItemBag, party: &burngfx::game::Party,
                     camps: &burngfx::game::Camps, rooms: &RoomItems, room_ids: &[Vec<u8>], types: &ItemTypes) -> bool {
    location == here
        || (camps.get(location).and_then(|c| c.owner) == Some(me)
            && radio_access(here, carried, party, rooms, room_ids, types)
            && radio_stored(location, rooms, room_ids, types))
}

/// `InfoScene.RenderNPCLine`'s details (v1.3): for each camper, by class in
/// INFO's rows (fighters, technicians, doctors) and camp order, his
/// experience tier plus one (`GetExperienceTier(Experience) + 1`, the
/// `~d` mark) and his health in sevenths, at least one (`~r`).
fn camp_details(city: usize, camps: &burngfx::game::Camps, people: &People, tier_width: i32) -> [Vec<(i32, i32)>; 3] {
    use burngfx::gamdat::CharClass;
    let mut out: [Vec<(i32, i32)>; 3] = Default::default();
    for c in camps.get(city).map_or(&[][..], |c| &c.residents[..]) {
        let row = match c.origin.and_then(|r| people.get_by_record(r)).map(|p| p.class) {
            Some(CharClass::Mercenary) => 0,
            Some(CharClass::Technician) => 1,
            Some(CharClass::Doctor) => 2,
            _ => continue,
        };
        let tier = burngfx::table_combat::experience_tier(c.experience, tier_width).unwrap_or(0) as i32 + 1;
        let health = ((c.needs.health.clamp(1, 100) * 7 + 99) / 100).clamp(1, 7);
        out[row].push((tier, health));
    }
    out
}

/// `RadioReport`'s numbers: the defenders who count, their strength, and
/// the place's food and water a day.
struct RadioNumbers {
    count: i32,
    strength: f32,
    food: i32,
    water: i32,
}

#[allow(clippy::too_many_arguments)]
fn radio_numbers(
    target: usize,
    me: usize,
    here: usize,
    leader_pack: &ItemBag,
    party: &burngfx::game::Party,
    camps: &burngfx::game::Camps,
    people: &People,
    rivals: &[burngfx::rival::Rival],
    bench: Option<&Benched>,
    book: &burngfx::rules::RuleBook,
    types: &ItemTypes,
    rooms: &RoomItems,
    room_ids: &[Vec<u8>],
    springs: &Springs,
    gam: &Gamdat,
    _pack: &Pack,
    food_now: i32,
) -> Option<RadioNumbers> {
    use burngfx::gamdat::CharClass;
    if !radio_available(target, me, here, leader_pack, party, camps, rooms, room_ids, types, gam) {
        return None;
    }
    let place = gam.locations.get(target)?;
    let hazard = place.danger;
    let class_of = |record: Option<usize>| record.and_then(|r| people.get_by_record(r)).map_or(CharClass::Mercenary, |p| p.class);
    let mut strength = 0.0f32;
    let mut count = 0;
    let mut add = |pack: &ItemBag, kit: &burngfx::combat::Kit, class: CharClass, xp: i32, health: i32, human: bool| {
        if health > 0 && matches!(class, CharClass::Boss | CharClass::Mercenary | CharClass::Technician | CharClass::Doctor) {
            strength += v12_combat::strength(book, types, pack, kit, class, xp, health, human, hazard);
            count += 1;
        }
    };
    if let Some(c) = camps.get(target).filter(|c| c.owner.is_some_and(|o| o != me)) {
        for r in &c.residents {
            add(&r.pack, &r.kit, class_of(r.origin), r.experience, r.needs.health, false);
        }
    }
    for r in rivals.iter().filter(|r| r.player != me && !r.dead && r.journey.is_none() && r.at == target) {
        add(&r.pack, &burngfx::combat::Kit::default(), CharClass::Boss, r.experience, r.needs.health, false);
        for c in &r.party.companions {
            add(&c.pack, &c.kit, class_of(c.origin), c.experience, c.needs.health, false);
        }
    }
    if let Some(b) = bench.filter(|b| b.seat != me && !b.dead && b.journey.is_none() && b.at_location == target) {
        add(&b.carried, &b.state.kit, CharClass::Boss, b.experience, b.state.needs.health, true);
        for c in &b.party.companions {
            add(&c.pack, &c.kit, class_of(c.origin), c.experience, c.needs.health, true);
        }
    }
    // `GetFoodProductionRate`: the one rate the camp's day uses.
    let food = food_now;
    let water = v12_source_water(target, springs, room_ids, rooms, types, book);
    Some(RadioNumbers { count, strength, food, water })
}

#[allow(clippy::too_many_arguments)]
fn radio_report(
    target: usize,
    me: usize,
    here: usize,
    leader_pack: &ItemBag,
    party: &burngfx::game::Party,
    camps: &burngfx::game::Camps,
    people: &People,
    rivals: &[burngfx::rival::Rival],
    bench: Option<&Benched>,
    book: &burngfx::rules::RuleBook,
    types: &ItemTypes,
    rooms: &RoomItems,
    room_ids: &[Vec<u8>],
    springs: &Springs,
    gam: &Gamdat,
    pack: &Pack,
    food_now: i32,
) -> Option<Vec<String>> {
    let RadioNumbers { count, strength, food, water } = radio_numbers(target, me, here, leader_pack, party, camps, people, rivals,
                                                                      bench, book, types, rooms, room_ids, springs, gam, pack, food_now)?;
    let text = localized(pack, "v12/radio").and_then(|b| core::str::from_utf8(b).ok()).unwrap_or("");
    let lines: Vec<&str> = text.lines().map(|l| { let l = l.trim_end(); l.strip_suffix('}').unwrap_or(l) }).collect();
    let line = |i: usize| lines.get(i).copied().unwrap_or("").to_string();
    let num = |n: i32| {
        let mut s = String::new();
        if n < 0 {
            s.push('-');
        }
        push_num(&mut s, n.unsigned_abs());
        s
    };
    let threat = line(7 + burngfx::v12_items::threat_level(strength).max(1) as usize);
    let name = location_name(pack, Some(gam), target);
    Some(vec![
        line(0).replace("{location}", &name),
        line(12).replace("{food}", &num(food)).replace("{water}", &num(water)),
        if count == 0 { line(1) } else { line(13).replace("{count}", &num(count)).replace("{threat}", &threat) },
    ])
}

/// One character typed on the map (`MapScene.OnKeyPress`): the `/petko`
/// command goes on, and the dialog opens when the word is complete.
fn cheat_type(c: char, typed: &mut burngfx::cheat::Command, dialog: &mut Option<talk::Talk>, view: &Viewport) {
    match typed.key(c) {
        burngfx::cheat::Typed::Open => {
            *dialog = Some(cheat_talk(view));
            println_("cheat: /petko typed, the dialog: Travel, Refill, Items");
        }
        burngfx::cheat::Typed::Taken => {
            let mut line = String::from("cheat: typed ");
            line.push_str(if typed.is_typing() { typed.typed() } else { "(dropped)" });
            println_(&line);
        }
        burngfx::cheat::Typed::Passed => {}
    }
}

/// `MapScene.ShowCheatDialog`: "Cheats" over an empty line, and Travel,
/// Refill and Items, each of which closes it (`Exit`). Opened with
/// `SetCharacter(character, conversation)`, so without the face; two lines
/// a page, so the answers at once.
fn cheat_talk(view: &Viewport) -> talk::Talk {
    use burngfx::dialog::{Action, Choice};
    let exit = Choice { burn: None, action: Action::Exit };
    talk::Talk {
        who: usize::MAX,
        face: 0,
        conv: burngfx::dialog::Conversation {
            file: 0,
            section: 0,
            choices: [exit, exit, exit],
            item: None,
            substitutes: false,
        },
        lines: vec![String::from(burngfx::cheat::TITLE), String::new()],
        choice_text: burngfx::cheat::CHOICES.map(String::from),
        more_text: String::new(),
        pages: burngfx::dialog::Pages { offset: 0, choosing: true },
        hover: None,
        at: talk_at(view),
        per_page: 2,
        show_face: false,
    }
}

/// **The Capture conversation** (`ConversationType.Capture`), made ready to
/// show: `men_500` section 3 and its one answer, `burn?490`, in the face of
/// the one who was to stay. `who` is his place in `People`, or `usize::MAX`
/// for a companion with no record (a prepared party).
fn capture_talk(pack: &Pack, face: u8, who: usize, view: &Viewport) -> talk::Talk {
    let conv = burngfx::dialog::capture();
    let text = men_text(pack, "men/500").and_then(|b| core::str::from_utf8(b).ok()).unwrap_or("");
    let lines = burngfx::dialog::section(text, conv.section as usize);
    let burn = |n: u32| resolve(pack, &burn_ref(n)).unwrap_or_default();
    let choice_text = conv.choices.map(|c| c.burn.map(burn).unwrap_or_default());
    talk::Talk {
        who,
        face,
        conv,
        pages: burngfx::dialog::Pages::open(lines.len()),
        lines,
        choice_text,
        more_text: burn(talk::MORE),
        hover: None,
        at: talk_at(view),
        per_page: 2,
        show_face: true,
    }
}

/// `ShowReport`'s window (`MapScene.cs:217-233`): three lines and "Okay"
/// (`newburn?45`) to close it — and no face: `SetCharacter(character,
/// conversation, textLinesPerPage: 3)` leaves `showFace` false
/// (`DialogWindow.cs:104-117`).
fn report_talk(pack: &Pack, face: u8, lines: Vec<String>, view: &Viewport) -> talk::Talk {
    let mut t = okay_talk(pack, face, lines, view);
    t.show_face = false;
    t
}

/// A room's refusal (`TryEnterRoom`, `LocationScene.cs:1316-1322`): the
/// hint in the face of the one who tried, `SetCharacter(chr, hint, true)`,
/// two lines a page, and "Okay".
fn hint_talk(pack: &Pack, face: u8, lines: Vec<String>, view: &Viewport) -> talk::Talk {
    let mut t = okay_talk(pack, face, lines, view);
    t.per_page = 2;
    t
}

fn okay_talk(pack: &Pack, face: u8, lines: Vec<String>, view: &Viewport) -> talk::Talk {
    use burngfx::dialog::{Action, Choice};
    let none = Choice { burn: None, action: Action::None };
    talk::Talk {
        who: usize::MAX,
        face,
        conv: burngfx::dialog::Conversation {
            file: 0,
            section: 0,
            choices: [none, none, Choice { burn: None, action: Action::Exit }],
            item: None,
            substitutes: false,
        },
        lines,
        choice_text: [String::new(), String::new(), v12_newburn(pack, 45)],
        more_text: String::new(),
        pages: burngfx::dialog::Pages { offset: 0, choosing: true },
        hover: None,
        at: talk_at(view),
        per_page: 3,
        show_face: true,
    }
}

/// **v1.2's item tooltip** (`ItemGridTooltip.BuildItemFacts`, U10): what an
/// item is for, in `tooltip.txt`'s lines, in v1.2's order — in use by the
/// viewer (equipped, or a function item carried), the damage at the
/// viewer's experience, the reach, food and water, a container's capacity,
/// what a trap yields, protection, Extended's functions, what it loads or
/// is loaded with, and the constructions it goes into (those made known by
/// the construction dialog named, the rest counted). `viewer` is who looks,
/// and the item's slot in his pack when it is there.
#[allow(clippy::too_many_arguments)]
fn item_facts(pack: &Pack, types: &ItemTypes, book: &burngfx::rules::RuleBook,
              constructions: &burngfx::construction::Constructions, productions: &burngfx::production::Productions,
              known: &[String], kind: usize,
              viewer: Option<(&burngfx::modern_ai::encounter::Fighter, Option<usize>)>) -> Vec<String> {
    use burngfx::gamdat::Danger;
    let text = localized(pack, "v12/tooltip").and_then(|b| core::str::from_utf8(b).ok()).unwrap_or("");
    let lines: Vec<&str> = text.trim_start_matches('\u{feff}').lines().map(|l| { let l = l.trim_end(); l.strip_suffix('}').unwrap_or(l) }).collect();
    let line = |i: usize| String::from(lines.get(i).copied().unwrap_or(""));
    let Some(t) = types.get(kind) else { return Vec::new() };
    let mut out = Vec::new();
    // `IsItemInUse`: carried, and the weapon, the armour or a function item.
    if let Some((f, Some(slot))) = viewer {
        if f.kit.weapon == Some(slot) || f.kit.protection == Some(slot) || !t.functions.is_empty() {
            out.push(line(if t.functions.is_empty() { 92 } else { 93 }));
        }
    }
    if let (false, Some((f, _))) = (t.damage_table.is_empty(), viewer) {
        // The blow with this weapon in hand: the viewer as he is, holding it.
        let mut holder = burngfx::modern_ai::encounter::Fighter {
            class: f.class, experience: f.experience, health: f.health,
            pack: ItemBag::with(1, &[kind]), kit: f.kit, human: f.human,
        };
        holder.kit.weapon = Some(0);
        let rules = burngfx::modern_ai::encounter::Rules { book, types, difficulty: 1, hazard: Danger::None };
        let (min, max) = rules.weapon_preview(&holder, 0);
        let mut range = panels::num(min);
        if max != min {
            range.push('-');
            range.push_str(&panels::num(max));
        }
        out.push(line(16).replace("{damage}", &range));
    }
    if t.attack_range > 0 {
        let reach = burngfx::encounter::Reach::from_range(t.attack_range as f32) as usize;
        out.push(line(87).replace("{reach}", &line(88 + reach)));
    }
    let (food, water) = (types.food_of(kind), types.water_of(kind));
    if food > 0 {
        out.push(line(33).replace("{food}", &panels::num(food)));
    }
    if water > 0 {
        out.push(line(34).replace("{water}", &panels::num(water)));
    }
    if let (0, Some(full)) = (water, types.full_of(kind)) {
        let capacity = types.water_of(full);
        if capacity > 0 {
            out.push(line(41).replace("{water}", &panels::num(capacity)));
        }
    }
    if let Some(p) = productions.worked_by(&t.name).and_then(|i| productions.get(i)) {
        out.push(line(40).replace("{food}", &panels::num(p.rate(1, 1, 0).food_per_day)));
    }
    let defense = types.defense_of(kind);
    if defense > 0 {
        out.push(line(36).replace("{defense}", &panels::num(defense)));
    }
    for (danger, n, key) in [(Danger::Gas, 37, "{gas}"), (Danger::Radiation, 38, "{radiation}")] {
        let rate = t.protection_against(danger);
        if rate > 0 {
            out.push(line(n).replace(key, &panels::num(rate as i32)));
        }
    }
    for (function, n) in [("remote_intel", 79), ("resting_sustenance", 80), ("creature_deterrent", 81), ("metal_detection", 82)] {
        if t.functions.iter().any(|f| f == function) {
            out.push(line(n));
        }
    }
    // Ammunition: what it is loaded into, or that it wants loading.
    let mut loads: Vec<usize> = Vec::new();
    for r in &t.loads {
        if let Some(i) = types.index_of(r) {
            if !loads.contains(&i) {
                loads.push(i);
            }
        }
    }
    if !loads.is_empty() {
        if loads.iter().any(|&r| types.empty_of(r) == Some(kind)) {
            out.push(line(83));
        } else {
            let names: Vec<String> = loads.iter().map(|&r| {
                let n = types.get(r).and_then(|x| x.load_name.clone()).unwrap_or_default();
                match n.strip_prefix("@tooltip?").and_then(|i| i.parse::<usize>().ok()) {
                    Some(i) => line(i),
                    None => resolve(pack, n.trim_start_matches('@')).unwrap_or(n),
                }
            }).collect();
            out.push(line(84).replace("{weapons}", &names.join(" / ")));
        }
    }
    // What it goes into: the known ones by name, the rest counted.
    let loaded: Vec<&str> = loads.iter().filter_map(|&r| types.name_of(r)).collect();
    let mut results: Vec<&str> = Vec::new();
    // `GetRecipes(game)`: the recipes this preset offers, by part or tool.
    for r in constructions.iter().filter(|r| r.available) {
        if r.uses(&t.name) && !loaded.contains(&r.result.as_str()) && !results.contains(&r.result.as_str()) {
            results.push(r.result.as_str());
        }
    }
    let known_results: Vec<&str> = results.iter().copied().filter(|r| known.iter().any(|k| k == r)).collect();
    let unknown = results.len() - known_results.len();
    let more_known = known_results.len() > 3;
    let limit = if unknown > 0 || more_known { 2 } else { 3 };
    for r in known_results.iter().take(limit) {
        let title = types.index_of(r).map(|i| item_name(pack, types, i)).unwrap_or_else(|| String::from(*r));
        out.push(line(43).replace("{recipe}", &title));
    }
    if unknown == 1 {
        out.push(line(44));
    } else if unknown > 1 {
        out.push(line(45).replace("{count}", &panels::num(unknown as i32)));
    } else if more_known {
        out.push(line(46));
    }
    out
}

/// v1.2's inventory lines for one member, in the classic look
/// (`InventoryWindow.OnRender`, `!IsNewGfx`): the damage of the weapon in
/// hand as `Dmg: x-y` beside `Def: N%` when armour counts and something is
/// worn, else `Damage: x-y` alone (`newburn?111`); then the protection worn
/// against gas and radiation (`newburn?90`, `91`), or an immune face's.
#[allow(clippy::too_many_arguments)]
fn v12_inventory_lines(pack: &Pack, types: &ItemTypes, book: &burngfx::rules::RuleBook,
                       class: Option<burngfx::gamdat::CharClass>, experience: i32, health: i32,
                       bag: &ItemBag, kit: combat::Kit, face: u8) -> (String, Option<String>, String) {
    use burngfx::gamdat::Danger;
    use burngfx::modern_ai::encounter::{Fighter, Rules};
    let rules = Rules { book, types, difficulty: 1, hazard: Danger::None };
    let fighter = Fighter {
        class: class.unwrap_or(burngfx::gamdat::CharClass::Boss),
        experience,
        health,
        pack: bag.clone(),
        kit,
        human: true,
    };
    let (min, max, defense) = rules.equipped_preview(&fighter);
    let mut damage = panels::num(min);
    if max != min {
        damage.push('-');
        damage.push_str(&panels::num(max));
    }
    let newburn = |n: usize, key: &str, value: &str| {
        let k = alloc::format!("{{{key}}}");
        // The text table keeps `{damage` of `{damage}}`: the line's closing
        // brace is taken as the end of the line.
        v12_newburn(pack, n).replace(&k, value).replace(k.trim_end_matches('}'), value)
    };
    let (left, right) = match defense {
        // NewGfx: `newburn?111` and `?112` (`InventoryWindow.cs:302-307`).
        Some(d) if gfx::newgfx() => (newburn(111, "damage", &damage), Some(newburn(112, "defense", &panels::num(d)))),
        Some(d) => {
            let mut dmg = String::from("Dmg: ");
            dmg.push_str(&damage);
            let mut def = String::from("Def: ");
            def.push_str(&panels::num(d));
            def.push('%');
            (dmg, Some(def))
        }
        // The text table keeps `{damage` of `{damage}}`: the line's closing
        // brace is taken as the end of the line.
        None => (v12_newburn(pack, 111).replace("{damage}", &damage).replace("{damage", &damage), None),
    };
    let mut hazard = String::new();
    // "Rad" in the classic look, "Radiation" in NewGfx (`:317`).
    let rad = if gfx::newgfx() { 92 } else { 91 };
    for (danger, label, immune) in [(Danger::Gas, 90, &book.rules.gas_immune_faces),
                                    (Danger::Radiation, rad, &book.rules.radiation_immune_faces)] {
        let rate = burngfx::v12_items::hazard_protection_rate(bag, kit.protection, danger, face, immune, types);
        if rate == 0 {
            continue;
        }
        if !hazard.is_empty() {
            hazard.push_str("  ");
        }
        hazard.push_str(&v12_newburn(pack, label));
        hazard.push_str(": ");
        hazard.push_str(&panels::num(rate as i32));
        hazard.push('%');
    }
    (left, right, hazard)
}

/// **Where the player's own Burntime data is**: `burntime.pack`, the
/// `music` and `sounds` drawers and (on AROS) `Saves`. The `data` argument,
/// else the variable `Burntime/Data` (`ENV:` on AROS, `BURNTIME_DATA`
/// elsewhere), else the drawer `Data` beside the program. The program
/// carries none of it (`NOTICE`); see `docs/distribution.md`.
fn data_dir() -> String {
    let mut dir = arg_value("data").or_else(data_variable).unwrap_or_else(data_beside_program);
    if !dir.ends_with('/') && !dir.ends_with(':') {
        dir.push('/');
    }
    dir
}

/// v1.2's `user.txt` (`UserSettings`): the player's own choices, as
/// `key=value` lines — `music`, `map_music`. On AROS `ENV:Burntime/user.txt`,
/// written to `ENVARC:` too so that it outlasts a reboot; on the host in
/// the data drawer. Missing is all defaults.
fn user_settings_paths() -> Vec<String> {
    if script_run() {
        // A scripted run keeps its choices to itself: in the directory it
        // runs in, never read back by the next run.
        vec![String::from("user.txt")]
    } else if cfg!(target_os = "aros") {
        vec![String::from("ENV:Burntime/user.txt"), String::from("ENVARC:Burntime/user.txt")]
    } else {
        let mut p = data_dir();
        p.push_str("user.txt");
        vec![p]
    }
}

fn user_setting(key: &str) -> Option<String> {
    if script_run() {
        return None;
    }
    let text = fetch(&user_settings_paths()[0]).ok()?;
    music::parse_songs(&text).into_iter().find(|(k, _)| k == key).map(|(_, v)| v)
}

/// F9 (`ToggleMusicMode`): the other set, kept as the `music` setting as
/// v1.2 keeps it when it closes; nothing while music is off.
fn toggle_music_set(music: &mut music::Music) {
    match music.toggle_set(&music_root()) {
        Some(mode) => {
            set_user_setting("music", mode);
            let mut line = String::from("f9: music ");
            line.push_str(mode);
            println_(&line);
        }
        None => println_("f9: nothing (music off, or no other set)"),
    }
}

/// v1.3's `NewGamePreferences.Store`: the start screen's three states into
/// `user.txt`, each written only when it differs from what is there.
fn remember_new_game(difficulty: u16, mode_state: u16, ai_state: u16) {
    for (key, value) in burngfx::start::preference_values(difficulty, mode_state, ai_state) {
        if user_setting(key).as_deref() != Some(value.as_str()) {
            set_user_setting(key, &value);
        }
    }
}

/// Write one setting, keeping the others.
fn set_user_setting(key: &str, value: &str) {
    let paths = user_settings_paths();
    let mut pairs = fetch(&paths[0]).map(|t| music::parse_songs(&t)).unwrap_or_default();
    match pairs.iter_mut().find(|(k, _)| k == key) {
        Some(p) => p.1 = String::from(value),
        None => pairs.push((String::from(key), String::from(value))),
    }
    let mut text = String::new();
    for (k, v) in &pairs {
        text.push_str(k);
        text.push('=');
        text.push_str(v);
        text.push('\n');
    }
    for path in &paths {
        #[cfg(target_os = "aros")]
        {
            let _ = aros::fs::create_dir_all(parent_of(path));
        }
        if let Err(why) = store(path, &text) {
            let mut line = String::from("settings: not written to ");
            line.push_str(path);
            line.push_str(": ");
            line.push_str(&why);
            println_(&line);
        }
    }
}

#[cfg(target_os = "aros")]
fn data_variable() -> Option<String> {
    // `ENV:` is a file system: the variable is the file's text.
    fetch("ENV:Burntime/Data").ok().map(|v| String::from(v.trim())).filter(|v| !v.is_empty())
}

#[cfg(not(target_os = "aros"))]
fn data_variable() -> Option<String> {
    std::env::var("BURNTIME_DATA").ok().filter(|v| !v.is_empty())
}

#[cfg(target_os = "aros")]
fn data_beside_program() -> String {
    String::from("PROGDIR:Data/")
}

#[cfg(not(target_os = "aros"))]
fn data_beside_program() -> String {
    std::env::current_exe()
        .ok()
        .and_then(|exe| exe.parent().map(|d| d.join("Data").to_string_lossy().into_owned()))
        .unwrap_or_else(|| String::from("Data"))
}

/// The game's data: the pack built in, when this build has one (a
/// developer's), else `burntime.pack` from [`data_dir`]. What to say when
/// there is none or it cannot be read.
fn game_pack() -> Result<Pack<'static>, Vec<String>> {
    if let Ok(p) = Pack::open(PACK) {
        if !p.is_empty() {
            return Ok(p);
        }
    }
    let dir = data_dir();
    let mut path = dir.clone();
    path.push_str("burntime.pack");
    let tell = |first: String| {
        let mut where_ = String::from("or say where it is: ");
        where_.push_str(if cfg!(target_os = "aros") {
            // `SetEnv` does not make the drawer a name like this lives in.
            "MakeDir ENV:Burntime ENVARC:Burntime, then SetEnv SAVE Burntime/Data <drawer>"
        } else {
            "BURNTIME_DATA=<directory>"
        });
        where_.push_str(", or `data <drawer>` when starting it.");
        let mut put = String::from("Make burntime.pack from your own copy of Burntime with the packer (see ReadMe)");
        put.push_str(" and put it in ");
        put.push_str(&dir);
        vec![first, String::from("This program carries none of Burntime's data."), put, where_]
    };
    let bytes = match read_pack_file(&path) {
        Ok(b) => b,
        Err(why) => {
            let mut first = String::from("no game data: cannot read ");
            first.push_str(&path);
            first.push_str(" (");
            first.push_str(&why);
            first.push(')');
            return Err(tell(first));
        }
    };
    let bytes: &'static [u8] = alloc::boxed::Box::leak(bytes.into_boxed_slice());
    match Pack::open(bytes) {
        Ok(p) if !p.is_empty() => {
            let mut line = String::from("game data: ");
            line.push_str(&path);
            println_(&line);
            Ok(p)
        }
        Ok(_) => {
            let mut first = String::from("no game data: ");
            first.push_str(&path);
            first.push_str(" is an empty pack");
            Err(tell(first))
        }
        Err(e) => {
            let mut first = String::from("no game data: ");
            first.push_str(&path);
            first.push_str(match e {
                burngfx::pack::PackError::NotAPack => " is not a burntime.pack",
                burngfx::pack::PackError::Malformed => " is damaged or cut short",
                burngfx::pack::PackError::UnsupportedVersion(_) => " was made by another version of the packer",
            });
            Err(tell(first))
        }
    }
}

/// A pack's bytes, into a buffer the size of the file: a pack with
/// NewGfx's pictures is over 50 MB, more than the fixed 32 MiB this read
/// into before; and the buffer is exactly full, so turning it into the
/// leaked slice does not copy it.
#[cfg(target_os = "aros")]
fn read_pack_file(path: &str) -> Result<Vec<u8>, String> {
    let size = file_size(path).ok_or_else(|| String::from("cannot examine it"))?;
    let mut buffer = vec![0u8; size];
    match aros::fs::read_into(path, &mut buffer) {
        Ok(used) => {
            buffer.truncate(used);
            Ok(buffer)
        }
        Err(e) => {
            let mut why = String::new();
            let _ = core::fmt::write(&mut why, format_args!("{e}"));
            Err(why)
        }
    }
}

#[cfg(not(target_os = "aros"))]
fn read_pack_file(path: &str) -> Result<Vec<u8>, String> {
    std::fs::read(path).map_err(|e| e.to_string())
}

/// A point moved by WASD's pan: the camera follows it instead of the
/// character, and `follow` keeps it to the map.
fn shifted(p: Point, by: (i32, i32)) -> Point {
    Point::new(p.x + by.0, p.y + by.1)
}

/// Who the selected character is for the target's lock, and where he
/// stands: the leader, a companion, or a camper of ours in this place.
fn actor_spot(selected: burngfx::save::Selection, state: &GameState, party: &game::Party, people: &People, here: usize) -> (u64, Point) {
    match selected {
        burngfx::save::Selection::Companion(id) => match party.companions.iter().find(|c| c.id == id) {
            Some(c) => (0x100 + id as u64, c.at),
            None => (0, state.position),
        },
        burngfx::save::Selection::Camper(record) => {
            match (0..people.len()).find(|&i| people.get(i).is_some_and(|p| p.record == record && p.location == here && !p.dead)) {
                Some(i) => (0x1_0000_0000 + record as u64, people.get(i).map_or(state.position, |p| p.at)),
                None => (0, state.position),
            }
        }
        burngfx::save::Selection::Leader => (0, state.position),
    }
}

fn point_distance(a: Point, b: Point) -> f32 {
    let (dx, dy) = ((a.x - b.x) as f32, (a.y - b.y) as f32);
    v12_combat::sqrt(dx * dx + dy * dy)
}

/// An item lying here, as a target's identity: its kind and its spot.
fn item_key(d: &burngfx::spawn::Dropped) -> u64 {
    ((d.kind as u64) << 32) | ((d.at.x as u16 as u64) << 16) | d.at.y as u16 as u64
}

/// `UpdateOverlay`'s candidates for the one standing at `at`: doors in
/// reach, items, people here and — when he is not one of the group — the
/// group; never himself or the dead.
#[allow(clippy::too_many_arguments)]
fn nearby_candidates(scene: &Scene, ground: &[burngfx::spawn::Dropped], people: &People, party: &game::Party, state: &GameState,
                     selected: burngfx::save::Selection, here: usize, at: Point) -> Vec<burngfx::targets::Candidate> {
    use burngfx::targets::{Candidate, Key};
    let doors: Vec<Candidate> = (0..scene.map.entrances.len())
        .filter(|&i| game::entrance_reached(&scene.map, i, at, scene.reach_of(i)))
        .filter_map(|i| game::entrance_distance_squared(&scene.map, i, at).map(|d| Candidate { key: Key::Door(i), distance: v12_combat::sqrt(d as f32) }))
        .collect();
    let items: Vec<Candidate> = ground.iter().filter(|d| d.location == here)
        .map(|d| Candidate { key: Key::Item(item_key(d)), distance: point_distance(d.at, at) })
        .collect();
    let in_group = !matches!(selected, burngfx::save::Selection::Camper(_));
    let mut people_near: Vec<Candidate> = people.at(here)
        .filter(|&i| people.get(i).is_some_and(|p| !p.dead && !p.hired))
        .filter(|&i| !matches!(selected, burngfx::save::Selection::Camper(r) if people.get(i).is_some_and(|p| p.record == r)))
        .map(|i| Candidate { key: Key::Person(i), distance: people.get(i).map_or(f32::MAX, |p| point_distance(p.at, at)) })
        .collect();
    if !in_group {
        people_near.push(Candidate { key: Key::Leader, distance: point_distance(state.position, at) });
        for c in party.companions.iter().filter(|c| c.needs.health > 0) {
            people_near.push(Candidate { key: Key::Friend(c.id), distance: point_distance(c.at, at) });
        }
    }
    burngfx::targets::candidates(&doors, &items, &people_near)
}

/// How far a character target is now, for keeping a lock (`CreateRetainedCharacterCandidate`).
fn key_distance(k: burngfx::targets::Key, at: Point, people: &People, party: &game::Party, state: &GameState) -> Option<f32> {
    use burngfx::targets::Key;
    match k {
        Key::Person(i) => people.get(i).filter(|p| !p.dead).map(|p| point_distance(p.at, at)),
        Key::Friend(id) => party.companions.iter().find(|c| c.id == id).map(|c| point_distance(c.at, at)),
        Key::Leader => Some(point_distance(state.position, at)),
        _ => None,
    }
}

/// Where a click on the target lands: a door's middle, an item, a body's
/// middle (as `clickon` aims).
fn key_point(k: burngfx::targets::Key, scene: &Scene, ground: &[burngfx::spawn::Dropped], people: &People, party: &game::Party,
             state: &GameState, here: usize) -> Option<Point> {
    use burngfx::targets::Key;
    match k {
        Key::Door(i) => scene.map.entrances.get(i).map(|e| Point::new(e.left + e.width / 2, e.top + e.height / 2)),
        Key::Item(id) => ground.iter().find(|d| d.location == here && item_key(d) == id).map(|d| d.at),
        Key::Person(i) => people.get(i).map(|p| Point::new(p.at.x, p.at.y - 8)),
        Key::Friend(id) => party.companions.iter().find(|c| c.id == id).map(|c| Point::new(c.at.x, c.at.y - 8)),
        Key::Leader => Some(Point::new(state.position.x, state.position.y - 8)),
    }
}

/// The target's label as `MapViewOverlayNearbyAction` draws it
/// (`MapViewHoverInfo`): the title, where it is centred on the map, and its
/// ink — a door its room's name over the entrance, `LightGray`; an item its
/// name, `(180, 152, 112)`; a character his name over his head, in his
/// player's colour if in that player's group, the darker one for a camper,
/// else `(252, 220, 0)`.
#[allow(clippy::too_many_arguments)]
fn target_label(k: burngfx::targets::Key, pack: &Pack, scene: &Scene, ground: &[burngfx::spawn::Dropped], people: &People,
                party: &game::Party, state: &GameState, types: &ItemTypes, leader: &hud::Leader,
                here: usize, blocked: bool) -> Option<(String, Point, u32)> {
    use burngfx::targets::Key;
    const ITEM_INK: u32 = 0x00B4_9870;
    const NOBODY_INK: u32 = 0x00FC_DC00;
    // `colorsdark[(int)color]`: the employer's.
    let dark = |seat: usize| seat_colours().ink_dark(seat);
    let named = |id: u16| resolve(pack, &burn_ref(id as u32)).unwrap_or_default();
    // `Character.MapArea`'s top is the feet less the body's sixteen.
    let over_head = |at: Point| Point::new(at.x, at.y - 16 - 10);
    match k {
        // In a place another player holds, every door is "Blocked"
        // (`AreEntrancesBlockedFor`, `newburn?103`), over its middle.
        Key::Door(i) if blocked => scene.map.entrances.get(i)
            .map(|e| (v12_newburn(pack, 103), Point::new(e.left + e.width / 2, e.top + e.height / 2 - 9), hud::HOVER_INK)),
        Key::Door(i) => scene.map.entrances.get(i)
            .map(|e| (describe(pack, scene, i).name, Point::new(e.left + e.width / 2, e.top - 10), hud::HOVER_INK)),
        Key::Item(id) => ground.iter().find(|d| d.location == here && item_key(d) == id)
            .map(|d| (item_name(pack, types, d.kind), Point::new(d.at.x, d.at.y - 4 - 10), ITEM_INK)),
        Key::Person(i) => people.get(i).map(|p| {
            let ink = p.employer.map_or(NOBODY_INK, dark);
            (named(p.name_id), over_head(p.at), ink)
        }),
        Key::Friend(id) => party.companions.iter().find(|c| c.id == id).map(|c| {
            let name = c.origin.and_then(|r| people.get_by_record(r)).map(|p| named(p.name_id)).unwrap_or_default();
            (name, over_head(c.at), leader.ink)
        }),
        Key::Leader => Some((leader.name.clone(), over_head(state.position), leader.ink)),
    }
}

/// `MapViewOverlayHoverText.GetLevel`: a percentage as one of `levels`
/// steps, at least the first.
fn bar_level(value: i32, levels: i32) -> i32 {
    ((value.clamp(1, 100) * levels + 99) / 100).clamp(1, levels)
}

/// `ShowTrapSelectedDialog` (`InventoryScene.cs:845-852`): `@dialogs?0`
/// with `|P` the production's produce, and `Conversation.Simple`'s one
/// answer, `@newburn?45`, which closes it.
fn trap_talk(pack: &Pack, types: &ItemTypes, productions: &burngfx::production::Productions, production: usize,
             scene_w: i32) -> talk::Talk {
    use burngfx::dialog::{Action, Choice};
    let text = localized(pack, "v12/dialogs").and_then(|b| core::str::from_utf8(b).ok()).unwrap_or("");
    let produce = productions.get(production).and_then(|p| types.index_of(&p.produce)).map_or(String::new(), |k| item_name(pack, types, k));
    let line = TextDb::parse(text.trim_start_matches('\u{feff}')).get(0).unwrap_or("").replace("|P", &produce);
    let none = Choice { burn: None, action: Action::None };
    let lines = vec![line, String::new()];
    talk::Talk {
        who: usize::MAX,
        face: 0,
        conv: burngfx::dialog::Conversation {
            file: 0,
            section: 0,
            choices: [none, none, Choice { burn: None, action: Action::Exit }],
            item: None,
            substitutes: false,
        },
        choice_text: [String::new(), String::new(), v12_newburn(pack, 45)],
        more_text: resolve(pack, &burn_ref(talk::MORE)).unwrap_or_default(),
        pages: burngfx::dialog::Pages::open(lines.len()),
        lines,
        hover: None,
        at: ((scene_w - talk::SIZE.0) / 2, (ROOM_H - talk::SIZE.1) / 2 - 10),
        per_page: 2,
        show_face: false,
    }
}

/// What [`item_prompt_facts`] reads of the game.
struct ItemFactsIn<'a> {
    types: &'a ItemTypes,
    productions: &'a burngfx::production::Productions,
    constructions: &'a burngfx::construction::Constructions,
    known: &'a [String],
    gam: Option<&'a Gamdat>,
    camps: &'a burngfx::game::Camps,
    springs: &'a Springs,
    rooms: &'a RoomItems,
    ground: &'a [burngfx::spawn::Dropped],
    room: Option<&'a Room>,
    pile: Option<Point>,
    is_water: bool,
    here: usize,
    /// The viewer's pack and kit, and his class.
    bag: &'a ItemBag,
    kit: &'a combat::Kit,
    viewer_class: burngfx::gamdat::CharClass,
    leader_class: Option<burngfx::gamdat::CharClass>,
    party: &'a game::Party,
    people: &'a People,
    needs: &'a game::CharacterNeeds,
    /// Who is in the leader's range, the leader first (`IsInRange`).
    reach: &'a [bool],
}

/// The focused item's facts for `InventoryScene.GetItemTooltipDetails`
/// (`burngfx::prompt_sets::item_details`). The construction is evaluated by
/// `GetConstructionInspector`: the viewer, or the first of the group who may
/// build from the item (`InventoryScene.cs:242,364,854-858`).
fn item_prompt_facts(g: &ItemFactsIn, kind: usize, in_inventory: bool, slot: usize) -> burngfx::prompt_sets::ItemFacts {
    use burngfx::prompt_sets::{BuildFacts, ItemFacts, ToolFacts};
    let name = g.types.name_of(kind).unwrap_or("");
    let t = g.types.get(kind);
    let names = |kinds: &mut dyn Iterator<Item = usize>| -> Vec<String> {
        kinds.filter_map(|k| g.types.name_of(k).map(String::from)).collect()
    };
    let nearby: Vec<String> = match (g.room, g.pile) {
        (Some(r), _) => g.rooms.get(g.here, r.index).map_or(Vec::new(), |b| names(&mut b.iter())),
        (None, Some(at)) => names(&mut burngfx::game::pick_items(g.ground, g.here, at).into_iter().filter_map(|i| g.ground.get(i).map(|d| d.kind))),
        _ => Vec::new(),
    };
    let carried = names(&mut g.bag.iter());
    // `CanSupplyGroup`: the leader and those in his range.
    let mut group: Vec<&game::CharacterNeeds> = vec![g.needs];
    group.extend(g.party.companions.iter().enumerate().filter(|(i, _)| g.reach.get(i + 1).copied().unwrap_or(true)).map(|(_, c)| &c.needs));
    let class_of = |c: &game::Companion| c.origin.and_then(|r| g.people.get_by_record(r)).map_or(burngfx::gamdat::CharClass::Mercenary, |q| q.class);
    let mut classes = vec![class_name(g.leader_class.unwrap_or(burngfx::gamdat::CharClass::Boss))];
    classes.extend(g.party.companions.iter().map(|c| class_name(class_of(c))));
    let recipes: Vec<&burngfx::construction::Recipe> = g.constructions.iter().filter(|r| r.available && r.uses(name)).collect();
    let build = (g.room.is_some() || g.pile.is_some())
        .then(|| g.constructions.find(g.constructions.inspector_class(class_name(g.viewer_class), &classes, name), name, &carried, &nearby))
        .flatten()
        .and_then(|o| g.constructions.get(o.recipe).map(|r| (o, r)))
        .map(|(o, r)| {
            let missing: Vec<&String> = r.items.iter().chain(r.tools.iter())
                .filter(|need| !carried.contains(need) && !nearby.contains(need))
                .collect();
            BuildFacts {
                can_build: o.can_build,
                known: g.known.contains(&r.result),
                loads_weapon: t.is_some_and(|t| t.loads.contains(&r.result)),
                only_ammunition: !missing.is_empty() && missing.iter().all(|m| m.as_str() == "item_ammunition"),
            }
        });
    ItemFacts {
        in_inventory,
        in_room: g.room.is_some(),
        water_source: g.is_water,
        reserve: g.springs.get(g.here).map_or(0, |w| w.reserve),
        food: g.types.food_of(kind),
        water: g.types.water_of(kind),
        hungry: group.iter().any(|n| n.food < n.max_food),
        thirsty: group.iter().any(|n| n.water < n.max_water),
        capacity: t.and_then(|t| t.full.as_deref()).and_then(|f| g.types.index_of(f)).map_or(0, |k| g.types.water_of(k)),
        selectable: selectable(g.types, kind).is_some(),
        equipped: in_inventory && (g.kit.weapon == Some(slot) || g.kit.protection == Some(slot)),
        tool: g.productions.worked_by(name).map(|p| ToolFacts {
            valid: g.gam.and_then(|m| m.locations.get(g.here)).is_some_and(|l| l.available_products.contains(&Some(p))),
            selected: g.camps.get(g.here).is_some_and(|c| c.production == Some(p)),
        }),
        in_recipes: !recipes.is_empty(),
        needs_technician: !recipes.iter().any(|r| classes.iter().any(|c| r.allows(c))),
        build,
    }
}

/// `GetTrapLevel`: the dots a production's traps show, by what they catch.
fn trap_level(productions: &burngfx::production::Productions, production: usize) -> i32 {
    match productions.get(production).map(|p| p.produce.as_str()) {
        Some("item_maggots") => 1,
        Some("item_rats") => 2,
        Some("item_snake") => 3,
        Some("item_meat") => 4,
        _ => 0,
    }
}

/// `AddTrapIcons`: a dot mark for each working trap of the place's
/// production, two at most.
fn trap_marks(marks: &mut Vec<hud::Mark>, productions: &burngfx::production::Productions, production: Option<usize>,
              tools: usize) {
    let Some(p) = production else { return };
    let level = trap_level(productions, p);
    let most = productions.get(p).map_or(0, |x| x.max_combination);
    for _ in 0..tools.min(most).min(2) {
        if level > 0 {
            marks.push(hud::Mark::new(hud::Bar::Dots, level));
        }
    }
}

/// `DrawCharacterText`'s marks: the experience tier as dots for one of the
/// viewer's people or nobody's (not a dog, a mutant or a trader), and the
/// health in seven steps for the viewer's own.
fn character_marks(class: burngfx::gamdat::CharClass, owner: Option<usize>, me: usize, experience: i32, health: i32,
                   tier_width: i32) -> Vec<hud::Mark> {
    use burngfx::gamdat::CharClass;
    let mut marks = Vec::new();
    let own = owner == Some(me);
    if !matches!(class, CharClass::Dog | CharClass::Mutant | CharClass::Trader) && (owner.is_none() || own) {
        let tier = burngfx::table_combat::experience_tier(experience, tier_width).unwrap_or(0) as i32;
        marks.push(hud::Mark::new(hud::Bar::Dots, tier + 1));
    }
    if own {
        marks.push(hud::Mark::new(hud::Bar::Red, bar_level(health, 7)));
    }
    marks
}

/// `DrawEntranceText` with the inventory hint (a door of the viewer's own
/// place): the room's food in thirds as a red bar, the production's traps
/// on the room they go to, and a spring's reserve as a blue bar.
#[allow(clippy::too_many_arguments)]
fn door_marks(room: usize, here: usize, scene: &Scene, rooms: &RoomItems, types: &ItemTypes,
              productions: &burngfx::production::Productions, production: Option<usize>, food_per_day: i32,
              tools: usize, springs: &Springs) -> Vec<hud::Mark> {
    use burngfx::game::ItemFacts;
    let mut marks = Vec::new();
    let food: i32 = rooms.get(here, room).map_or(0, |b| b.iter().map(|k| types.food(k)).filter(|&f| f > 0).sum());
    if food / 3 > 0 {
        marks.push(hud::Mark::new(hud::Bar::Red, food / 3));
    }
    if let Some(p) = production.filter(|_| food_per_day > 0) {
        // The room a trap goes to: the first holding one of the
        // production's tools, unless it is full; else the first not full.
        let count = scene.room_ids.len();
        let full = |r: usize| rooms.get(here, r).is_some_and(|b| b.is_full());
        let works = |r: usize| rooms.get(here, r).is_some_and(|b| b.iter()
            .any(|k| types.name_of(k).is_some_and(|n| productions.get(p).is_some_and(|x| x.worked_by(n)))));
        let target = match (0..count).find(|&r| works(r)) {
            Some(r) if !full(r) => Some(r),
            _ => (0..count).find(|&r| !full(r)),
        };
        if target == Some(room) {
            trap_marks(&mut marks, productions, Some(p), tools);
        }
    }
    if scene.is_water_source(room) {
        if let Some(s) = springs.get(here) {
            marks.push(hud::Mark::new(hud::Bar::Blue, s.reserve));
        }
    }
    marks
}

/// The marks on a label in a place: a character's, or a door's in the
/// viewer's own camp (`showInventoryHint`).
#[allow(clippy::too_many_arguments)]
fn label_marks(k: burngfx::targets::Key, me: usize, here: usize, blocked: bool, leader_experience: i32, state: &GameState,
               party: &game::Party, people: &People, camps: &burngfx::game::Camps, scene: &Scene, rooms: &mut RoomItems,
               ground: &mut Vec<burngfx::spawn::Dropped>, room_ids: &[Vec<u8>], walk: &[Option<WalkGrid>],
               types: &ItemTypes, productions: &burngfx::production::Productions, springs: &Springs,
               book: Option<&burngfx::rules::RuleBook>, rivals: &[burngfx::rival::Rival], gam: Option<&Gamdat>)
               -> Vec<hud::Mark> {
    use burngfx::gamdat::CharClass;
    use burngfx::targets::Key;
    let Some(book) = book else { return Vec::new() };
    let width = book.rules.experience_tier_width;
    let class_of = |record: Option<usize>| record.and_then(|r| people.get_by_record(r)).map_or(CharClass::Mercenary, |p| p.class);
    match k {
        Key::Leader => character_marks(CharClass::Boss, Some(me), me, leader_experience, state.needs.health, width),
        Key::Friend(id) => party.companions.iter().find(|c| c.id == id)
            .map(|c| character_marks(class_of(c.origin), Some(me), me, c.experience, c.needs.health, width))
            .unwrap_or_default(),
        Key::Person(i) => people.get(i)
            .map(|p| character_marks(p.class, p.employer, me, p.experience, p.needs.health, width))
            .unwrap_or_default(),
        Key::Door(i) if !blocked && camps.get(here).and_then(|c| c.owner) == Some(me) => {
            let v = v12_world(book, rivals, people, gam);
            let production = camps.get(here).and_then(|c| c.production);
            let storage = WorldStorage {
                rooms,
                ground,
                room_ids,
                walk,
                types,
                productions,
                rng: burngfx::spawn::Rng::seeded(0),
                products: Vec::new(),
            };
            use burngfx::game::Storage;
            let food = camps.get(here).and_then(|c| c.production.map(|p| (c, p))).map_or(0, |(c, p)| {
                burngfx::v12_day::food_rate(here, c, &storage, productions, types, &v, p)
            });
            let tools = production.map_or(0, |p| storage.tools(here, p));
            door_marks(i, here, scene, storage.rooms, types, productions, production, food, tools, springs)
        }
        _ => Vec::new(),
    }
}

/// What a place's label shows on the world map (`DrawWorldLocationText`).
struct PlaceMarks {
    marks: Vec<hud::Mark>,
    icon: Option<hud::Icon>,
}

/// `DrawWorldLocationText`'s marks for `place` as `me` sees it: his own
/// camp's people, food a day, traps and water; another's what his radio
/// reports, or a visited place's spring; and the danger, once he has been
/// there or has a radio.
#[allow(clippy::too_many_arguments)]
fn place_marks(place: usize, me: usize, g: &Gamdat, camps: &burngfx::game::Camps, visited: bool, radio: bool,
               report: Option<&RadioNumbers>, food_per_day: i32, water: i32, tools: usize,
               productions: &burngfx::production::Productions, springs: &Springs) -> PlaceMarks {
    let mut marks = Vec::new();
    let Some(l) = g.locations.get(place) else { return PlaceMarks { marks, icon: None } };
    let camp = camps.get(place);
    let production = camp.and_then(|c| c.production);
    let icon = if visited || radio {
        match l.danger {
            burngfx::gamdat::Danger::Gas => Some(hud::Icon::Toxic),
            burngfx::gamdat::Danger::Radiation => Some(hud::Icon::Radiation),
            _ => None,
        }
    } else {
        None
    };
    if camp.and_then(|c| c.owner) == Some(me) {
        let people = camp.map_or(0, |c| c.residents.iter().filter(|r| r.needs.health > 0).count()) as i32;
        if people > 0 {
            marks.push(hud::Mark { bar: hud::Bar::People, value: people, gap_after: true });
        }
        if food_per_day > 0 {
            marks.push(hud::Mark::new(hud::Bar::Red, food_per_day));
        }
        trap_marks(&mut marks, productions, production, tools);
        marks.push(hud::Mark::new(hud::Bar::Blue, water));
    } else if let Some(r) = report {
        if r.count > 0 {
            marks.push(hud::Mark { bar: hud::Bar::People, value: r.count, gap_after: true });
        }
        if r.food > 0 {
            marks.push(hud::Mark::new(hud::Bar::Red, r.food));
        }
        trap_marks(&mut marks, productions, production, tools);
        marks.push(hud::Mark::new(hud::Bar::Blue, r.water));
    } else if visited && !l.is_city {
        marks.push(hud::Mark::new(hud::Bar::Blue, springs.get(place).map_or(0, |s| s.refresh)));
    }
    PlaceMarks { marks, icon }
}

/// `MapScene.ShowCityReport`: how many of the city's neighbours the player
/// still lacks, or that he holds them all and with them the city, and how
/// many cities there are to hold (`cityinfo.txt`).
fn city_report(pack: &Pack, g: &Gamdat, camps: &burngfx::game::Camps, city: usize, me: usize) -> Vec<String> {
    // `{missing}` and the rest are arguments here, so a line ends only at a
    // `}` that closes it, as `radio.txt`'s do.
    let text = localized(pack, "v12/cityinfo").and_then(|b| core::str::from_utf8(b).ok()).map_or("", |t| t.trim_start_matches('\u{feff}'));
    let lines: Vec<&str> = text.lines().map(|l| { let l = l.trim_end(); l.strip_suffix('}').unwrap_or(l) }).collect();
    let line = |i: usize| String::from(lines.get(i).copied().unwrap_or(""));
    let mut neighbours: Vec<usize> = Vec::new();
    for r in g.locations.get(city).map_or(&[][..], |l| &l.roads[..]) {
        if !neighbours.contains(&r.neighbour) {
            neighbours.push(r.neighbour);
        }
    }
    let owner = |n: usize| camps.get(n).and_then(|c| c.owner);
    let missing = neighbours.iter().filter(|&&n| owner(n) != Some(me)).count() as i32;
    // `ControllingPlayer`: every neighbour held by one player.
    let controlled = !neighbours.is_empty() && neighbours.iter().all(|&n| owner(n) == Some(me));
    let total = g.locations.iter().filter(|l| l.is_city).count() as i32;
    let args = [("{missing}", missing), ("{neighbors}", neighbours.len() as i32), ("{total}", total)];
    let get = |i: usize| panels::text_helper(&line(i), &args);
    if controlled { vec![get(3), get(4), get(2)] } else { vec![get(0), get(1), get(2)] }
}

/// Who v1.2's frame shows: the selected character's face, name and health
/// in the player's ink, and where he stands in the group (`i/n`, only when
/// the group is more than one; a camper is not in it, so the count reads 1
/// as `MainUiOriginalWindow`'s does).
#[allow(clippy::too_many_arguments)]
fn selected_for_hud(selected: burngfx::save::Selection, leader: &hud::Leader, state: &GameState, party: &game::Party,
                    people: &People, camps: &burngfx::game::Camps, pack: &Pack, me: usize)
                    -> (hud::Leader, i32, Option<(usize, usize)>) {
    use burngfx::save::Selection;
    let size = 1 + party.companions.len();
    let party_at = |i: usize| (size > 1).then_some((i, size));
    let named = |p: &burngfx::hire::Person| resolve(pack, &burn_ref(p.name_id as u32)).unwrap_or_default();
    let mine = (hud::Leader { name: leader.name.clone(), face: leader.face, ink: leader.ink }, state.needs.health, party_at(0));
    match selected {
        Selection::Leader => mine,
        Selection::Companion(id) => match party.companions.iter().position(|c| c.id == id) {
            Some(n) => {
                let c = &party.companions[n];
                let person = c.origin.and_then(|r| people.get_by_record(r));
                // A companion with no record (a prepared party) is called
                // as the cycling's notice calls him.
                let name = person.map(named).filter(|n| !n.is_empty()).unwrap_or_else(|| {
                    let mut n = String::from("companion ");
                    push_num(&mut n, id as u32);
                    n
                });
                (hud::Leader { name, face: person.map_or(0, |p| p.face_id as i32), ink: leader.ink },
                 c.needs.health, party_at(1 + n))
            }
            None => mine,
        },
        Selection::Camper(record) => {
            let person = (0..people.len()).filter_map(|i| people.get(i)).find(|p| p.record == record && !p.dead);
            let resident = camped_as(camps, record).and_then(|(l, at)| camps.get(l).and_then(|c| c.residents.get(at)));
            match (person, resident) {
                (Some(p), Some(r)) if p.employer == Some(me) => {
                    (hud::Leader { name: named(p), face: p.face_id as i32, ink: leader.ink }, r.needs.health, party_at(0))
                }
                _ => mine,
            }
        }
    }
}

/// The target, for the log: a room by name, an item, somebody.
#[allow(clippy::too_many_arguments)]
fn describe_target(k: burngfx::targets::Key, pack: &Pack, scene: &Scene, ground: &[burngfx::spawn::Dropped], people: &People,
                   types: &ItemTypes, leader: &hud::Leader) -> String {
    use burngfx::targets::Key;
    match k {
        Key::Door(i) => {
            let mut s = String::from("door ");
            s.push_str(&describe(pack, scene, i).name);
            s
        }
        Key::Item(id) => ground.iter().find(|d| item_key(d) == id).map_or(String::from("an item"), |d| item_name(pack, types, d.kind)),
        Key::Person(i) => {
            let mut s = String::from(people.get(i).map_or("somebody", |p| class_name(p.class)));
            if let Some(p) = people.get(i) {
                s.push_str(" (record ");
                push_num(&mut s, p.record as u32);
                s.push(')');
            }
            s
        }
        Key::Friend(id) => {
            let mut s = String::from("companion ");
            push_num(&mut s, id as u32);
            s
        }
        Key::Leader => leader.name.clone(),
    }
}

/// A line of v1.2's own `newburn.txt` (`@newburn?N` in a v1.2 game).
/// A line of v1.2's `BURN.TXT` in a v1.2 game, read as v1.2's
/// `ResourceManager.GetString` reads one: only a last `}` taken off. The
/// statistics' `{cheats}}` (`burn?571`) keeps its placeholder that way,
/// where [`TextDb`] would end the line at its first `}`.
fn v12_burn_whole(pack: &Pack, index: u32) -> Option<String> {
    if !v12_texts() {
        return None;
    }
    let text = core::str::from_utf8(pack.get("v12/burn")?).ok()?;
    let line = text.lines().nth(index as usize)?.trim_end();
    Some(String::from(line.strip_suffix('}').unwrap_or(line)))
}

fn v12_newburn(pack: &Pack, index: usize) -> String {
    localized(pack, "v12/newburn")
        .and_then(|b| core::str::from_utf8(b).ok())
        .and_then(|t| TextDb::parse(t).get(index).map(String::from))
        .unwrap_or_default()
}

fn print_classic_turn(player: usize, done: &burngfx::classic_ai::Done, log: &[String],
                      rival: &burngfx::rival::Rival, pack: &Pack, gam: Option<&Gamdat>) {
    let Some(ai) = rival.classic.as_ref() else { return };
    let mut line = String::from("player ");
    push_num(&mut line, player as u32);
    line.push_str(" (classic) at ");
    line.push_str(&location_name(pack, gam, rival.at));
    line.push_str(", ");
    line.push_str(ai.mode.name());
    if !done.took.is_empty() {
        line.push_str(", took ");
        push_num(&mut line, done.took.len() as u32);
        line.push_str(" off the ground");
    }
    for l in log {
        line.push_str("; ");
        line.push_str(l);
    }
    if let Some(to) = done.set_out {
        line.push_str("; sets out for ");
        line.push_str(&location_name(pack, gam, to));
    }
    if done.refreshed {
        line.push_str("; topped up");
    }
    line.push_str("; group of ");
    push_num(&mut line, (1 + rival.party.len()) as u32);
    line.push_str(", pool");
    for (id, n) in &ai.pool.items {
        line.push(' ');
        line.push_str(id.strip_prefix("item_").unwrap_or(id));
        line.push('x');
        push_num(&mut line, *n);
    }
    println_(&line);
}

/// `Player.Name`: a human's, as typed; a machine player's is its
/// character's, record *i* of `gam.dat`.
fn player_name(seat: usize, humans: &[burngfx::save::Human], pack: &Pack, gam: Option<&Gamdat>) -> String {
    if let Some(h) = humans.iter().find(|h| h.seat == seat) {
        return h.name.clone();
    }
    gam.and_then(|g| g.characters.get(seat))
        .and_then(|c| resolve(pack, &burn_ref(c.name_id as u32)))
        .unwrap_or_default()
}

/// `WaitScene` handing over: whose turn, on which day, with how much of the
/// day's one clock left.
fn print_turn(me: usize, humans: &[burngfx::save::Human], day: u16, left_ms: u32, round_ms: u32) {
    let mut line = String::from("turn: player ");
    push_num(&mut line, me as u32);
    if let Some(h) = humans.iter().find(|h| h.seat == me) {
        line.push_str(" (");
        line.push_str(&h.name);
        line.push(')');
    }
    line.push_str(" plays day ");
    push_num(&mut line, day as u32);
    line.push_str(", ");
    push_num(&mut line, left_ms / 1000);
    line.push_str(" of ");
    push_num(&mut line, round_ms / 1000);
    line.push_str(" s left");
    println_(&line);
}

fn print_sound(file: &str, played: music::Played, engine: burngfx::game::Engine) {
    let mut line = String::from("sound: ");
    line.push_str(file);
    line.push_str(match (played, engine) {
        (music::Played::InsteadOfMusic, _) => ", played once in place of the music (v0.9.1 PlayOnce)",
        (music::Played::OverMusic, _) => ", over the music on a voice of its own (New PlaySound)",
        (music::Played::Silent, _) => " due, not played: no audio or no file",
    });
    println_(&line);
}

fn print_change_sound(played: music::Played, engine: burngfx::game::Engine) {
    println_(match (played, engine) {
        (music::Played::InsteadOfMusic, _) => "sound: change.ogg, played once in place of the music (v0.9.1 PlayOnce)",
        (music::Played::OverMusic, _) => "sound: change.ogg, over the music on a voice of its own (New PlaySound)",
        (music::Played::Silent, burngfx::game::Engine::V091) => "sound: change.ogg due (PlayOnce), not played: no audio or no file",
        (music::Played::Silent, _) => "sound: change.ogg due (PlaySound), not played: no audio or no file",
    });
}

