/// Where `sounds/*.ogg` are: v0.9.1's `resources/game/classic/sounds`,
/// read from disk at run time as the music is.
fn sounds_root() -> String {
    #[cfg(target_os = "aros")]
    {
        arg_value("soundsdir").unwrap_or_else(|| {
            let mut dir = data_dir();
            dir.push_str("sounds/");
            dir
        })
    }
    #[cfg(not(target_os = "aros"))]
    {
        arg_value("soundsdir").unwrap_or_else(|| {
            String::from(concat!(env!("CARGO_MANIFEST_DIR"), "/../burngfx/testdata/classic/sounds/"))
        })
    }
}

/// Who plays which seat, and where each human stands.
fn print_humans(humans: &[burngfx::save::Human], me: usize, pack: &Pack, gam: Option<&Gamdat>,
                at: usize, bench: Option<&Benched>) {
    for h in humans {
        let mut line = String::from("human: player ");
        push_num(&mut line, h.seat as u32);
        line.push_str(" is ");
        line.push_str(&h.name);
        line.push_str(", ");
        line.push_str(h.color.word());
        line.push_str(", at ");
        let place = if h.seat == me { Some(at) } else { bench.filter(|b| b.seat == h.seat).map(|b| b.at_location) };
        line.push_str(&place.map(|l| location_name(pack, gam, l)).unwrap_or_default());
        if h.seat == me {
            line.push_str(" (playing)");
        }
        println_(&line);
    }
}

