/// How the game ended, said once.
/// The player's own standing, and nothing about anybody else's — see
/// `rivals::standing_of` for why that restraint is the source's and not
/// squeamishness.
fn print_standing(s: &burngfx::rivals::Standing, scenario: Option<(usize, usize)>) {
    // **The condition's own count, under the condition's own words.** Always
    // the real rule and the real total, whatever a scenario has asked for:
    // writing a shortened goal here would tell the player a different rule
    // from the one being played.
    let mut line = String::from("   to win, hold every location beside a city: ");
    push_num(&mut line, s.wanted_held as u32);
    line.push_str(" of ");
    push_num(&mut line, s.wanted as u32);
    println_(&line);

    // The original's own statistics, kept because they are the original's,
    // and labelled so that they are not read as progress towards the
    // condition — they count a city as controlled without looking at its
    // city neighbours, and the condition looks at everything.
    let mut line = String::from("   the game's own count: cities ");
    push_num(&mut line, s.cities as u32);
    line.push_str(", of them controlled ");
    push_num(&mut line, s.controlled as u32);
    line.push_str(", places held ");
    push_num(&mut line, s.held as u32);
    println_(&line);

    // A scenario gets its own line and its own words.
    if let Some((held, asked)) = scenario {
        let mut line = String::from("   this scenario asks for the first ");
        push_num(&mut line, asked as u32);
        line.push_str(" of those: ");
        push_num(&mut line, held as u32);
        line.push_str(" held");
        println_(&line);
    }
}

fn print_decided(decision: burngfx::rivals::Decision, goals: Option<usize>) {
    let mut line = String::new();
    match decision {
        burngfx::rivals::Decision::Won(0) => line.push_str("you have won"),
        burngfx::rivals::Decision::Won(p) => {
            line.push_str("player ");
            push_num(&mut line, p as u32);
            line.push_str(" has won");
        }
        // **A defeat is not about holdings.** `World.Turn` ends a player the
        // moment their own character dies, whatever they hold, so saying it
        // in the victory condition's words would name the wrong rule.
        burngfx::rivals::Decision::Lost(0) => {
            println_("you have lost: your character is dead, and everything they held with them");
            println_("close the window to quit (escape too, with the test keys).");
            return;
        }
        burngfx::rivals::Decision::Lost(p) => {
            let mut line = String::from("player ");
            push_num(&mut line, p as u32);
            line.push_str(" is out: their character is dead");
            println_(&line);
            println_("close the window to quit (escape too, with the test keys).");
            return;
        }
    }
    line.push_str(": every location beside a city");
    if let Some(n) = goals {
        line.push_str(", of the ");
        push_num(&mut line, n as u32);
        line.push_str(" this scenario asks for");
    }
    println_(&line);
    println_("close the window to quit (escape too, with the test keys).");
}

