/// Who is near enough to have a page in an inventory window: the leader
/// always, and every companion within fifty of them. It is what the doctor's
/// and the diner's pages are built from — `InventoryWindow.SetGroup`.
/// `Group.IsInRange(leader, member)` for every page, the leader's first —
/// measured from `center`, the character the inventory belongs to: the
/// player's own, or a companion selected.
fn within_fifty(party: &burngfx::game::Party, leader_at: Point, center: Point) -> Vec<bool> {
    let mut reach = Vec::with_capacity(party.companions.len() + 1);
    reach.push(game::in_group_range(center, leader_at));
    for who in &party.companions {
        reach.push(game::in_group_range(center, who.at));
    }
    reach
}

/// Why the doctor will not, in the player's words.
fn doctor_refusal(why: burngfx::doctor::Refusal) -> &'static str {
    use burngfx::doctor::Refusal::*;
    match why {
        NothingToTreatWith => "put some medicine on the table",
        NotMedicine => "that is not medicine",
        TooMuchOnTheTable => "the table holds four",
        NoSuchSlot | SlotNamedTwice => "that pick no longer means anything",
        NoSuchPatient => "nobody there to treat",
        TheyAreDead => "they are beyond a doctor",
        OutOfReach { .. } => "they are too far off to be in here with you",
    }
}

