    /// A v1.2 Options scene on its Settings page, with nothing read from a
    /// pack: what the page's logic needs.
    fn settings_page(fullscreen: Option<bool>) -> super::screens::Options {
        let mut o = super::screens::Options {
            page: super::screens::Page::Saves,
            name: String::new(),
            slots: Vec::new(),
            list_error: None,
            from_menu: false,
            songs: Vec::new(),
            jukebox: true,
            playing: None,
            t: super::screens::OptionTexts::default(),
            v12: Some(super::screens::V12Options { tab_focus: 3, tabs_focused: true, ..Default::default() }),
            player: String::new(),
            keyboard: true,
            choices: super::screens::Choices { fullscreen, ..Default::default() },
        };
        // Down the tabs to Settings, and Left into the page.
        o.key(super::screens::OptionsKey::Left);
        o
    }

    /// `OptionsSettingsPage` (OptionsSettingsPage.cs:25-243): seven lines
    /// from (38, 58), ten apart — graphics, fullscreen, music, map music,
    /// controller glyphs, prompts, language — in the keys' order; the keys
    /// skip what is not enabled (the fullscreen line hidden without
    /// `SupportsFullscreenToggle`, `:92-96`), entering the page focuses the
    /// first enabled (`SetKeyboardActive(…, resetFocus)`) — the graphics,
    /// which switch the look (UI-19) — and Primary chooses the focused line.
    #[test]
    fn the_settings_page_has_v12s_seven_lines() {
        use super::screens::{setting_at, OptionsClick as C, OptionsKey as K, Setting, SETTINGS12};
        assert_eq!(SETTINGS12, [Setting::Graphics, Setting::Fullscreen, Setting::Music, Setting::MapMusic,
                                Setting::Controller, Setting::Prompts, Setting::Language]);
        assert_eq!((setting_at(0), setting_at(1), setting_at(4), setting_at(6)), ((38, 58), (38, 68), (38, 98), (38, 118)));
        // The window can be switched: the graphics line first, then it.
        let mut o = settings_page(Some(false));
        assert_eq!(o.key(K::Primary), C::ToggleGraphics);
        o.key(K::Down);
        assert_eq!(o.key(K::Primary), C::ToggleFullscreen);
        o.key(K::Down);
        assert_eq!(o.key(K::Primary), C::CycleMusic);
        o.key(K::Down);
        o.key(K::Down);
        assert_eq!(o.key(K::Primary), C::CycleController);
        o.key(K::Down);
        assert_eq!(o.key(K::Primary), C::TogglePrompts);
        o.key(K::Down);
        assert_eq!(o.key(K::Primary), C::CycleLanguage);
        // Round, to the graphics.
        o.key(K::Down);
        assert_eq!(o.key(K::Primary), C::ToggleGraphics);
        o.key(K::Up);
        assert_eq!(o.key(K::Primary), C::CycleLanguage);
        // It cannot: no fullscreen line, the music after the graphics.
        let mut o = settings_page(None);
        assert!(!o.setting_enabled(Setting::Fullscreen));
        assert_eq!(o.key(K::Primary), C::ToggleGraphics);
        o.key(K::Down);
        assert_eq!(o.key(K::Primary), C::CycleMusic);
        o.key(K::Up);
        o.key(K::Up);
        assert_eq!(o.key(K::Primary), C::CycleLanguage);
    }

    /// The choices' cycles and their `user.txt` values (`Application.cs:
    /// 157-170, 244-334`; `ConfigSection.GetBool`/`Set(bool)` `:237-249,
    /// 445-452`): glyphs Auto → Xbox → PlayStation → Steam → Switch; the
    /// prompts Full ↔ Hide (Less counts as shown); the language Auto →
    /// English → German; and the texts each shows.
    #[test]
    fn the_settings_choices_cycle_and_are_kept_as_v12_keeps_them() {
        use super::screens::{Choices, Setting};
        assert_eq!((0..6).scan(0u8, |c, _| { let now = *c; *c = Choices::next_controller(now); Some(now) }).collect::<Vec<_>>(), [0, 1, 2, 3, 4, 0]);
        assert_eq!((Choices::next_prompts(0), Choices::next_prompts(1), Choices::next_prompts(2)), (2, 2, 0));
        assert_eq!((Choices::next_language(0), Choices::next_language(1), Choices::next_language(2)), (1, 2, 0));
        assert_eq!(Choices::controller_name(2), "playstation");
        assert_eq!(Choices::controller_of("PlayStation"), 2);
        assert_eq!(Choices::controller_of("nonsense"), 0);
        assert_eq!((Choices::language_name(0), Choices::language_name(1), Choices::language_name(2)), ("auto", "en", "de"));
        assert_eq!((Choices::language_of("German"), Choices::language_of("en"), Choices::language_of("")), (2, 1, 0));
        assert_eq!((Choices::prompts_of("2"), Choices::prompts_of("7"), Choices::prompts_of("-1"), Choices::prompts_of("x")), (2, 2, 0, 0));
        assert!(Choices::bool_of("on") && Choices::bool_of("True") && Choices::bool_of("1") && !Choices::bool_of("off"));
        let mut o = settings_page(Some(true));
        o.t.fullscreen = [String::from("Fullscreen ON"), String::from("Fullscreen OFF")];
        o.t.prompt_mode = [String::from("UI Hints SHOW"), String::from("UI Hints HIDE")];
        o.t.language_mode = [String::from("Language AUTO"), String::from("Language ENGLISH"), String::from("Language GERMAN")];
        assert_eq!(o.setting_text(Setting::Fullscreen), "Fullscreen ON");
        o.choices.fullscreen = Some(false);
        assert_eq!(o.setting_text(Setting::Fullscreen), "Fullscreen OFF");
        o.choices.prompts = 1;
        assert_eq!(o.setting_text(Setting::Prompts), "UI Hints SHOW");
        o.choices.prompts = 2;
        assert_eq!(o.setting_text(Setting::Prompts), "UI Hints HIDE");
        o.choices.language = 2;
        assert_eq!(o.setting_text(Setting::Language), "Language GERMAN");
    }

    /// `OptionsJukeboxPage.CreateSongButtons`: the list's entries with their
